css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

:root{
  --green:#0B5D3B; --green-d:#06331F; --green-dd:#042418; --green-l:#12764C; --green-x:#2FA46F;
  --teal:#0E7C6B; --teal-l:#14A08B;
  --gold:#B8901F; --gold-l:#D9B54A; --gold-bg:#FBF3DC; --gold-br:#EAD9A6;
  --mint:#E9F5ED; --mint-2:#D7ECE0; --mint-3:#BFDFCE;
  --ink:#12211A; --ink-2:#3C5347; --ink-3:#6A7C72; --ink-4:#95A39B;
  --cream:#FAF7EF; --cream-2:#F4EFE2; --card:#FFFFFF;
  --line:#E7E2D5; --line-2:#D8D2C2; --line-g:#DCE8E1;
  --ok:#17794E; --ok-bg:#E6F4EC; --ok-br:#BEE1CD;
  --warn:#9A6B05; --warn-bg:#FBF1DA; --warn-br:#EBD8A6;
  --crit:#9E2C22; --crit-bg:#FAE9E6; --crit-br:#EEC5BE;
  --info:#1E4E86; --info-bg:#E9F0F9; --info-br:#C6D8EE;
  --sp:#5F3C93; --sp-bg:#F0EAFA; --sp-br:#D9CBF0;
  --r:10px; --r-s:7px; --r-xs:5px;
  --sh:0 1px 2px rgba(18,33,26,.05),0 2px 6px rgba(18,33,26,.05);
  --sh-2:0 4px 16px rgba(18,33,26,.10);
  --sh-3:0 18px 48px rgba(6,35,22,.28);
  --sans:"Segoe UI",Inter,-apple-system,BlinkMacSystemFont,Roboto,"Helvetica Neue",Arial,sans-serif;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,"Times New Roman",serif;
  --mono:"SF Mono",ui-monospace,"Cascadia Mono",Consolas,monospace;
}
.navbar { display: none; }
.web-footer { display: none; }
*{box-sizing:border-box}
html,body{margin:0;padding:0;max-width:100%}
body{background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:13.4px;line-height:1.45;-webkit-font-smoothing:antialiased}
button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:1px}
.tnum{font-variant-numeric:tabular-nums}
.mono{font-family:var(--mono);font-size:11.4px;letter-spacing:-.2px}
.sp{flex:1}

/* ---------- REPORT HEADER (published-page style, testing v51 retained) ---------- */
.rhead{
  background:
    linear-gradient(
      120deg,
      #06331F 0%,
      #0B5D3B 48%,
      #0E6B44 100%
    );

  color:#EAF4EE;

  /* space for portal back button */
  padding:12px 18px 12px 58px;

  display:flex;
  align-items:center;
  gap:14px;

  box-shadow:
    0 1px 0 rgba(255,255,255,.09) inset,
    0 3px 14px rgba(6,35,22,.22);

  border-radius:0;
}

.report-title-wrap{
  min-width:0;
}

.rhead h1{
  margin:0;
  font-family:var(--serif);
  font-size:21px;
  font-weight:600;
  letter-spacing:.01em;
  color:#fff;
  line-height:1.15;
}

.rhead .kick{
  font-size:9.5px;
  letter-spacing:.3em;
  text-transform:uppercase;
  color:#9FCDB4;
  font-weight:700;
  margin-bottom:2px;
}

.rhead .who{
  display:flex;
  align-items:center;
  gap:9px;
  background:rgba(255,255,255,.09);
  border:1px solid rgba(255,255,255,.15);
  border-radius:22px;
  padding:4px 13px 4px 4px;
}

.rhead .who .av{
  width:28px;
  height:28px;
  border-radius:50%;
  background:linear-gradient(150deg,#2FA46F,#0B5D3B);
  display:grid;
  place-items:center;
  font-size:11px;
  font-weight:800;
  color:#fff;
}

.rhead .who b{
  display:block;
  font-size:12px;
  color:#fff;
  line-height:1.2;
}

.rhead .who span{
  display:block;
  font-size:8.8px;
  letter-spacing:.14em;
  color:#9FCDB4;
  text-transform:uppercase;
}

/* no unwanted space above the report header */
.page{
  padding:0 14px 14px;
  max-width:100%;
}

.sheet{
  background:#fff;
  border:1px solid var(--line);
  border-radius:12px;
  box-shadow:var(--sh-2);
  overflow:hidden;
}

/* ---------- TYPE SWITCH ---------- */
.tsw{display:flex;gap:0;background:var(--green-dd);padding:0 10px;flex-wrap:wrap;border-bottom:3px solid var(--gold)}
.tsw a{display:flex;align-items:center;gap:7px;padding:9px 15px;color:#A9CDBA;font-size:12.6px;font-weight:700;
  cursor:pointer;border-bottom:3px solid transparent;margin-bottom:-3px;white-space:nowrap}
.tsw a:hover{color:#fff;background:rgba(255,255,255,.05)}
.tsw a.on{color:#fff;background:rgba(255,255,255,.10);border-bottom-color:var(--gold-l)}
.tsw a .n{background:rgba(255,255,255,.14);border-radius:9px;padding:0 7px;font-size:10.2px;font-weight:800;line-height:17px}
.tsw a.on .n{background:var(--gold-l);color:#3A2B03}

/* ---------- FILTERS ---------- */
.filters{background:linear-gradient(180deg,#FFFDF8,#F6F2E6);border-bottom:1px solid var(--line);
  padding:10px 14px;display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end}
.fl{display:flex;flex-direction:column;gap:3px;min-width:126px}
.fl.w{min-width:196px}.fl.s{min-width:100px}
.fl label{font-size:9.4px;text-transform:uppercase;letter-spacing:.12em;color:var(--ink-2);font-weight:800}
.fl input,.fl select{padding:6px 9px;border:1px solid var(--line-2);border-radius:var(--r-xs);background:#fff;width:100%;font-size:12.4px}
.fl input:focus,.fl select:focus{border-color:var(--teal)}
.presets{display:flex;gap:5px;flex-wrap:wrap;padding:8px 14px;background:var(--cream-2);border-bottom:1px solid var(--line);align-items:center}
.chip{display:inline-flex;align-items:center;gap:5px;padding:3px 11px;border-radius:20px;background:#fff;border:1px solid var(--line-2);font-size:11.6px;cursor:pointer;font-weight:650}
.chip:hover{background:var(--gold-bg);border-color:var(--gold-br)}
.chip.on{background:linear-gradient(160deg,#12764C,#0B5D3B);color:#fff;border-color:#0B5D3B}
.plb{font-size:9.4px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);font-weight:800;margin-right:3px}
.btn{display:inline-flex;align-items:center;gap:6px;padding:6px 13px;border:1px solid var(--line-2);background:#fff;border-radius:var(--r-xs);cursor:pointer;font-size:12.2px;font-weight:650;transition:.12s;white-space:nowrap;box-shadow:var(--sh)}
.btn:hover{background:var(--cream);border-color:var(--ink-4)}
.btn.p{background:linear-gradient(160deg,#12764C,#0B5D3B);border-color:#0B5D3B;color:#fff}
.btn.p:hover{filter:brightness(1.09)}
.btn.g{background:linear-gradient(160deg,#D9B54A,#B8901F);border-color:#A87C12;color:#3A2B03}
.btn.s{background:linear-gradient(160deg,#14A08B,#0B6155);border-color:#0B6155;color:#fff}
.btn.sm{padding:3px 9px;font-size:11.2px}
.btn:disabled{opacity:.45;cursor:not-allowed}
.btnrow{display:flex;gap:7px;flex-wrap:wrap;align-items:center}

/* ---------- KPI ---------- */
.kpis{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:9px;padding:12px 14px 4px}
@media(max-width:1400px){.kpis{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:820px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
.tile{background:#fff;border:1px solid var(--line);border-left:3px solid var(--green);border-radius:var(--r-s);
  padding:9px 11px 10px;box-shadow:var(--sh);cursor:pointer;transition:transform .13s,box-shadow .13s}
.tile:hover{transform:translateY(-2px);box-shadow:var(--sh-2)}
.tile .v{font-family:var(--serif);font-size:23px;font-weight:600;line-height:1.05;color:var(--green)}
.tile .k{font-size:9.2px;letter-spacing:.13em;text-transform:uppercase;color:var(--ink-2);font-weight:800;margin-top:5px}
.tile .d{font-size:10.8px;color:var(--ink-3);margin-top:2px;line-height:1.35}
.tile.t-gold{border-left-color:var(--gold)} .tile.t-gold .v{color:var(--gold)}
.tile.t-crit{border-left-color:var(--crit)} .tile.t-crit .v{color:var(--crit)}
.tile.t-warn{border-left-color:#C98A0B} .tile.t-warn .v{color:var(--warn)}
.tile.t-ok{border-left-color:var(--ok)} .tile.t-ok .v{color:var(--ok)}
.tile.t-info{border-left-color:var(--info)} .tile.t-info .v{color:var(--info)}
.tile.t-teal{border-left-color:var(--teal)} .tile.t-teal .v{color:var(--teal)}
.tile.t-sp{border-left-color:var(--sp)} .tile.t-sp .v{color:var(--sp)}

/* ---------- ANALYTIC STRIP ---------- */
.astrip{display:grid;grid-template-columns:1.1fr 1.1fr 1.3fr;gap:10px;padding:10px 14px 2px}
@media(max-width:1200px){.astrip{grid-template-columns:1fr}}
.abox{background:#fff;border:1px solid var(--line);border-radius:var(--r-s);box-shadow:var(--sh);overflow:hidden}
.abox>h4{margin:0;padding:7px 11px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;
  color:var(--green);background:var(--mint);border-bottom:1px solid var(--mint-3);display:flex;align-items:center;gap:7px}
.abox>h4 .sp{flex:1}.abox>h4 em{font-style:normal;font-size:9.4px;color:var(--ink-3);letter-spacing:.06em}
.abody{padding:8px 11px 10px;max-height:196px;overflow-y:auto}
.hbar{display:flex;align-items:center;gap:8px;padding:2.5px 0;cursor:pointer}
.hbar:hover .lb{color:var(--green)}
.hbar .lb{width:118px;flex:0 0 118px;font-size:11.4px;color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hbar .tr{flex:1;height:9px;background:var(--mint);border-radius:20px;overflow:hidden;border:1px solid var(--mint-3)}
.hbar .tr i{display:block;height:100%;background:linear-gradient(90deg,#12764C,#2FA46F);border-radius:20px}
.hbar .tr i.w{background:linear-gradient(90deg,#C98A0B,#E5B441)}
.hbar .tr i.c{background:linear-gradient(90deg,#9E2C22,#C4574A)}
.hbar .vl{width:62px;text-align:right;font-weight:750;font-size:11.6px;flex:0 0 62px}
.feed{padding:2px 0}
.fitem{display:grid;grid-template-columns:28px minmax(0,1fr);gap:10px;align-items:center;padding:9px 8px;border-bottom:1px dashed var(--line);cursor:pointer;border-radius:6px}
.fitem:last-child{border-bottom:0}
.fitem:hover{background:var(--mint)}
.fitem .ic{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;font-size:11px;color:#fff;background:linear-gradient(155deg,#2FA46F,#0B5D3B);box-shadow:inset 0 1px 0 rgba(255,255,255,.4),0 2px 4px rgba(6,35,22,.25);font-style:normal}
.fitem .ic.gold{background:linear-gradient(155deg,#E8C868,#A87C12)}
.fitem .ic.teal{background:linear-gradient(155deg,#28BFA9,#0B6155)}
.fitem .ic.blue{background:linear-gradient(155deg,#5A93D6,#1B4278)}
.fitem .ic.plum{background:linear-gradient(155deg,#9A78D1,#4A2C7C)}
.fitem .ic.rose{background:linear-gradient(155deg,#DE7A6C,#8A2419)}
.fitem .fbody{min-width:0;display:grid;gap:5px}
.fitem .frow{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;min-width:0}
.fitem .fleft{min-width:0;display:flex;align-items:center;gap:5px;flex-wrap:wrap}
.fitem .fright{min-width:0;text-align:right;white-space:nowrap}
.fitem .fmain{font-size:11.5px;font-weight:800;line-height:1.2;color:var(--ink)}
.fitem .ftype{font-size:10.8px;color:#55766A;font-weight:750}
.fitem .freq{font-family:var(--mono);font-size:9.5px;color:#74877D;margin-left:2px}
.fitem .fsub{font-size:9.8px;color:var(--ink-3)}
.fitem .fperson{font-size:10.8px;color:var(--green);font-weight:800}
.fitem .frole{font-size:9.8px;color:var(--ink-3);padding-left:6px;border-left:1px solid var(--line-2)}
.fitem .fbranch{font-size:11px;color:var(--ink-2);font-weight:800}
.fitem .fmeta{font-size:9.7px;color:var(--ink-3)}
.fitem .fage{color:var(--green);font-weight:800}
@media(max-width:900px){
  .fitem .frow{grid-template-columns:1fr;gap:2px}
  .fitem .fright{text-align:left;white-space:normal}
}

/* ---------- TABLE ---------- */
.tbar{display:flex;align-items:center;gap:9px;padding:9px 14px 7px;flex-wrap:wrap}
.tbar b{font-family:var(--serif);font-size:16px;font-weight:600}
.tbar .cnt{font-size:11.4px;color:var(--ink-3)}
.tw{width:100%;max-width:100%;overflow:auto;border-top:1px solid var(--line);max-height:none}
table.tb{width:100%;border-collapse:collapse;font-size:12px}
table.tb th{background:linear-gradient(180deg,#0B5D3B,#06331F);color:#EAF4EE;font-size:9.3px;text-transform:uppercase;
  letter-spacing:.1em;font-weight:800;text-align:left;padding:7px 8px;white-space:nowrap;position:sticky;top:0;z-index:5;
  border-right:1px solid rgba(255,255,255,.09);cursor:pointer;vertical-align:middle}
table.tb th:hover{background:linear-gradient(180deg,#12764C,#0B5D3B)}
table.tb th em{display:block;font-style:normal;font-size:8.4px;letter-spacing:.08em;color:#9FCDB4;font-weight:650;margin-top:1px;text-transform:none}
table.tb th.nos{cursor:default}
table.tb td{padding:4px 8px;border-bottom:1px solid var(--line-g);border-right:1px solid #F1EEE4;vertical-align:middle;line-height:1.25}
table.tb tbody tr:nth-child(even){background:#F7FAF8}
table.tb tbody tr:hover{background:var(--mint)!important}
table.tb tbody tr.rej{background:#FDF1EF}
table.tb tbody tr.rej:nth-child(even){background:#FAE9E6}
table.tb tbody tr.pend{background:#FFFBF0}
table.tb tbody tr.pend:nth-child(even){background:#FBF3DC}
table.tb td.r,table.tb th.r{text-align:right}
table.tb td.c,table.tb th.c{text-align:center}
table.tb tfoot td{background:var(--green-dd);color:#EAF4EE;font-weight:800;padding:7px 8px;font-size:11.4px;position:sticky;bottom:0}
.l1{font-size:11.9px;font-weight:700;color:var(--ink);white-space:nowrap}
.l1.wrap{white-space:normal}
.l2{font-size:10.3px;color:var(--ink-3);white-space:nowrap;margin-top:1px}
.l2.wrap{white-space:normal}
.l2 b{color:var(--ink-2);font-weight:700}
.tag{display:inline-flex;align-items:center;gap:4px;padding:0 7px;border-radius:20px;font-size:9.8px;font-weight:800;line-height:16px;white-space:nowrap;border:1px solid transparent;text-transform:uppercase;letter-spacing:.04em}
.t-g{background:var(--ok-bg);color:var(--ok);border-color:var(--ok-br)}
.t-y{background:var(--warn-bg);color:var(--warn);border-color:var(--warn-br)}
.t-r{background:var(--crit-bg);color:var(--crit);border-color:var(--crit-br)}
.t-b{background:var(--info-bg);color:var(--info);border-color:var(--info-br)}
.t-p{background:var(--sp-bg);color:var(--sp);border-color:var(--sp-br)}
.t-n{background:#F1EFE7;color:var(--ink-2);border-color:var(--line-2)}
.t-m{background:var(--mint);color:var(--green);border-color:var(--mint-3)}
.t-au{background:var(--gold-bg);color:#7A5F09;border-color:var(--gold-br)}
.eye{width:26px;height:24px;border-radius:6px;border:1px solid var(--mint-3);background:var(--mint);color:var(--green);
  display:inline-grid;place-items:center;cursor:pointer;font-size:12.5px;box-shadow:var(--sh)}
.eye:hover{background:linear-gradient(160deg,#12764C,#0B5D3B);color:#fff;border-color:#0B5D3B}
.ok-i{color:var(--ok);font-weight:800}
.pend-i{color:var(--warn);font-weight:800}
.rej-i{color:var(--crit);font-weight:800}
.aged{color:var(--crit);font-weight:800}
.empty{padding:40px 16px;text-align:center;color:var(--ink-3)}
.empty b{display:block;font-size:15px;color:var(--ink-2);margin-bottom:4px;font-family:var(--serif)}
.pager{display:flex;align-items:center;gap:9px;padding:9px 14px;border-top:1px solid var(--line);background:var(--cream-2);flex-wrap:wrap}
.pager .pg{font-size:11.8px;color:var(--ink-2);font-weight:700}

/* ---------- MODAL ---------- */
.life-approval-overlay{position:fixed;inset:0;background:rgba(6,35,22,.58);display:none;align-items:flex-start;justify-content:center;z-index:200;padding:22px 14px;overflow-y:auto;backdrop-filter:blur(2px)}
.life-approval-overlay.on{display:flex}
.life-approval-modal{position:relative;display:block;height:auto;inset:auto;background:#fff;border-radius:14px;box-shadow:var(--sh-3);width:100%;max-width:1240px;overflow:hidden;animation:pop .17s ease}
@keyframes pop{from{opacity:0;transform:scale(.985) translateY(7px)}to{opacity:1;transform:none}}
.life-approval-modal>header{display:flex;align-items:center;gap:12px;padding:12px 18px;background:linear-gradient(120deg,#06331F,#0B5D3B);color:#fff}
.life-approval-modal>header h3{margin:0;font-size:16px;font-weight:600;font-family:var(--serif)}
.life-approval-modal>header .sub{font-size:11px;color:#A9CDBA;letter-spacing:.05em}
.life-approval-modal>header .x{cursor:pointer;font-size:22px;line-height:1;opacity:.85;padding:0 4px}
.life-approval-modal>header .x:hover{opacity:1}
.life-approval-modal>.body{padding:15px;max-height:calc(100vh - 176px);overflow-y:auto;background:var(--cream)}
.life-approval-modal>footer{display:flex;gap:8px;justify-content:flex-end;padding:10px 18px;border-top:1px solid var(--line);background:#fff;flex-wrap:wrap}

/* ---------- DETAIL BLOCKS ---------- */
.dhead{background:linear-gradient(125deg,#06331F,#0B5D3B 62%,#0E6B44);color:#fff;border-radius:var(--r);padding:13px 16px;margin-bottom:11px;display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.dhead .id{font-size:10.2px;letter-spacing:.16em;color:#9FCDB4;font-weight:700;text-transform:uppercase}
.dhead h2{margin:2px 0 0;font-family:var(--serif);font-size:24px;font-weight:600;line-height:1.1}
.dhead .meta{font-size:12px;color:#CFE3D8;margin-top:4px}
.dhead .meta b{color:#fff}
.pill{display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,.11);border:1px solid rgba(255,255,255,.18);
  border-radius:7px;padding:5px 10px;font-size:11.4px;color:#EAF4EE;margin:3px 5px 0 0}
.pill b{color:#fff}
.g2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.g3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.g4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
@media(max-width:900px){.g2,.g3,.g4{grid-template-columns:1fr}}
.box{background:#fff;border:1px solid var(--line);border-radius:var(--r-s);padding:11px 13px;box-shadow:var(--sh)}
.box.mint{background:var(--mint);border-color:var(--mint-3)}
.box.blue{background:var(--info-bg);border-color:var(--info-br)}
.box.gold{background:var(--gold-bg);border-color:var(--gold-br)}
.box>.hd{font-size:9.4px;letter-spacing:.15em;text-transform:uppercase;color:var(--ink-3);font-weight:800;margin-bottom:5px}
.box .big{font-family:var(--serif);font-size:19px;font-weight:600;line-height:1.15}
.box .sub2{font-size:11.4px;color:var(--ink-3);margin-top:3px}
.kv{display:flex;justify-content:space-between;gap:10px;padding:4px 0;border-bottom:1px dashed var(--line);font-size:12.2px}
.kv:last-child{border-bottom:0}
.kv span{color:var(--ink-3)}
.kv b{font-weight:700;text-align:right}
.sec{display:flex;align-items:center;gap:9px;margin:14px 0 8px}
.sec b{font-size:12.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--green)}
.sec i{flex:1;height:1px;background:var(--line);display:block}
.sec .cnt{font-size:10px;background:var(--gold-bg);border:1px solid var(--gold-br);color:#7A5F09;border-radius:20px;padding:1px 9px;font-weight:800}
.chain{display:flex;gap:0;flex-wrap:wrap;background:#fff;border:1px solid var(--line);border-radius:var(--r-s);overflow:hidden;box-shadow:var(--sh)}
.chain .st{flex:1;min-width:200px;padding:10px 12px;border-right:1px solid var(--line);position:relative}
.chain .st:last-child{border-right:0}
.chain .st .rl{font-size:9.4px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);font-weight:800}
.chain .st .pn{font-size:13.2px;font-weight:750;margin-top:3px}
.chain .st .dt{font-size:11.2px;color:var(--ink-3);margin-top:2px}
.chain .st.done{background:var(--ok-bg)} .chain .st.done .pn{color:var(--ok)}
.chain .st.wait{background:var(--warn-bg)} .chain .st.wait .pn{color:var(--warn)}
