.tline{position:relative;padding-left:20px;margin-top:4px}
.tline::before{content:"";position:absolute;left:4px;top:8px;bottom:10px;width:1px;background:var(--line-2)}
.tline .ev{position:relative;padding:0 0 12px 0;font-size:12.2px}
.tline .ev::before{content:"";position:absolute;left:-20px;top:4px;width:9px;height:9px;border-radius:50%;background:var(--green);border:2px solid #fff;box-shadow:0 0 0 1px var(--mint-3)}
.tline .ev.w::before{background:var(--warn)} .tline .ev.r::before{background:var(--crit)}
.tline .ev b{font-size:12.6px;font-weight:750}
