/* ---------- Compact bulk approval panel ---------- */
.life-bulk-summary{
  background:#e9f1e4;
  border:1px solid #cbbb82;
  border-radius:6px;
  padding:8px 12px;
  font-size:13.5px;
  margin-bottom:10px;
}
.life-bulk-ok   { color:#0B5D3B; font-weight:800; }
.life-bulk-warn { color:#9A6B05; font-weight:800; }

.life-bulk-list{
  list-style:none;
  margin:0 0 12px;
  padding:0;
  max-height:44vh;
  overflow:auto;
  border:1px solid #e0d6b2;
  border-radius:6px;
}
.life-bulk-row{
  display:grid;
  grid-template-columns: 150px 110px 1fr 90px 40px;
  align-items:center;
  gap:8px;
  padding:6px 9px;
  border-bottom:1px dashed #e6dcc0;
  font-size:12.5px;
}
.life-bulk-row:last-child{ border-bottom:0; }
.life-bulk-reqid  { font-family:var(--mono); font-size:11.5px; color:#173f2d; font-weight:700; }
.life-bulk-branch { color:#435b4c; }
.life-bulk-client { color:#173f2d; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.life-bulk-val    { text-align:right; font-variant-numeric:tabular-nums; font-weight:700; color:#173f2d; }
.life-bulk-view{
  background:#0B5D3B; color:#fff; border:0; border-radius:5px;
  width:28px; height:26px; cursor:pointer; font-size:14px;
}
.life-bulk-view:hover{ background:#0a4e32; }

.life-bulk-remarks{ margin:10px 0; }
.life-bulk-remarks label{
  display:block; font-size:12px; font-weight:800; color:#345b45;
  text-transform:uppercase; letter-spacing:.03em; margin-bottom:4px;
}
.life-bulk-remarks textarea{
  width:100%; border:1px solid #cbbb82; border-radius:6px;
  padding:7px 9px; font:13px/1.4 var(--sans); resize:vertical;
  background:#fffdf5;
}

.life-bulk-actions{
  display:flex; justify-content:flex-end; gap:8px; margin-top:10px;
}
.life-bulk-cancel{
  background:#fff; border:1px solid #cbbb82; color:#34553d;
  padding:8px 14px; border-radius:6px; cursor:pointer; font-weight:650;
}
.life-bulk-approve{
  background:#0B5D3B; color:#fff; border:0;
  padding:9px 18px; border-radius:6px; cursor:pointer; font-weight:750;
}
.life-bulk-approve:hover{ background:#0a4e32; }

.life-bulk-note{
  font-size:12px; color:#556b5b; margin-top:8px; line-height:1.45;
}
.life-bulk-note-warn{
  background:#fff6d9; border-left:3px solid #c49b21;
  padding:7px 10px; border-radius:0 5px 5px 0; color:#624d19;
}
.life-bulk-results{
  list-style:none; margin:0; padding:0;
  max-height:50vh; overflow:auto;
  border:1px solid #e0d6b2; border-radius:6px;
}
.life-bulk-results li{
  padding:6px 10px; border-bottom:1px dashed #e6dcc0; font-size:13px;
}
.life-bulk-results li:last-child{ border-bottom:0; }

.life-bulk-sign-wrap{
  border:1.5px dashed #aebfb5;border-radius:9px;background:#fff;overflow:hidden;
}
.life-bulk-sign-wrap canvas{
  display:block;width:100%;height:150px;touch-action:none;cursor:crosshair;
}
.life-bulk-sign-foot{
  display:flex;gap:10px;align-items:center;margin-top:7px;
  font-size:10.5px;color:#718079;
}
.life-bulk-sign-clear{
  border:1px solid #c8d6ce;background:#fff;border-radius:6px;
  padding:6px 9px;cursor:pointer;
}
/* Approval review readability */
#life-help-panel .life-help-card.life-bulk-card{width:min(1320px,96vw);max-height:92dvh;padding:22px;border:2px solid #d9b54a;box-shadow:0 24px 70px #04241855}
#life-help-panel .life-bulk-list{max-height:48vh;padding:0;scrollbar-gutter:stable}
#life-help-panel .life-bulk-row{margin:0;padding:13px 12px;gap:14px;background:#fffdf5;border-bottom:1px solid #e1dccb;align-items:start}
#life-help-panel .life-bulk-row:nth-of-type(even){background:linear-gradient(#0b5d3b0d,#0b5d3b0d),#fffdf5}
#life-help-panel .life-purchase-row,#life-help-panel .life-purchase-head{display:grid;grid-template-columns:minmax(145px,1.12fr) minmax(120px,1fr) minmax(170px,1.4fr) minmax(150px,1.3fr) minmax(85px,.7fr) minmax(95px,.75fr) 38px;gap:14px}
#life-help-panel .life-purchase-head{position:sticky;top:0;z-index:1;margin:0;padding:10px 12px;background:#124632;color:#fff;font-size:11px;font-weight:750;text-transform:uppercase;letter-spacing:.035em}
#life-help-panel .life-purchase-row>span{min-width:0;overflow-wrap:anywhere;line-height:1.5}
#life-help-panel .life-bulk-client{white-space:normal;overflow:visible;font-size:12px}
#life-help-panel .life-bulk-reqid{font-size:11px}
#life-help-panel .life-bulk-person small,#life-help-panel .life-bulk-items small{display:block;color:#617368;font-size:10.5px;line-height:1.5}
#life-help-panel .life-bulk-person b{display:block;font-size:12px;font-weight:650}
#life-help-panel .life-bulk-person small:not(:first-child){margin-top:5px}
#life-help-panel .life-bulk-items{font-size:12px}
#life-help-panel .life-bulk-val{white-space:nowrap;font-size:12px}
#life-help-panel .life-bulk-view{padding:0;width:32px;height:32px;min-width:32px}
#life-help-panel .life-row-ineligible{grid-column:1/-1;color:#9e2c22}
#life-help-panel .life-bulk-actions{justify-content:center;align-items:center;flex-wrap:wrap;gap:14px;margin:12px 0}
#life-help-panel .life-bulk-actions .life-bulk-cancel{background:#fce8e6;color:#963b34;border:1.5px solid #d9b54a;padding:12px 24px;min-height:44px;border-radius:8px}
#life-help-panel .life-bulk-actions .life-bulk-approve{background:#0b5d3b;color:#fff;border:1.5px solid #d9b54a;padding:12px 28px;min-height:44px;border-radius:8px;font-weight:750;box-shadow:0 3px 9px #0b5d3b22}
#life-help-panel .life-bulk-actions .life-bulk-approve:hover{background:#08482e}
#life-help-panel .life-bulk-actions .life-bulk-cancel:hover{background:#f8d8d4}
#life-help-panel button:focus-visible{outline:3px solid #d9b54a;outline-offset:3px}
#life-help-panel .life-bulk-note{text-align:center}
#life-help-panel .life-result-summary{padding:12px 16px;border-radius:8px;margin-bottom:14px;font-weight:700}
#life-help-panel .life-result-success{background:#e8f4ec;color:#155d39}
#life-help-panel .life-result-error{background:#fce8e6;color:#963b34}
@media(max-width:1000px){#life-help-panel .life-purchase-head{display:none}#life-help-panel .life-purchase-row{grid-template-columns:1fr 1fr;gap:12px 20px}#life-help-panel .life-purchase-row>span:before{content:attr(data-label);display:block;font-size:10px;font-weight:750;text-transform:uppercase;color:#617368;margin-bottom:4px}#life-help-panel .life-bulk-val{text-align:left}}
@media(max-width:600px){#life-help-panel{padding:8px}#life-help-panel .life-help-card.life-bulk-card{width:100%;padding:12px;max-height:96dvh}#life-help-panel .life-bulk-list{max-height:42dvh}#life-help-panel .life-bulk-actions button{width:100%}#life-help-panel .life-purchase-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}}



/* =====================================================================
   LIFE APPROVALS DASHBOARD — thin title bar + readable cards (override)
   Web Page: approvals-report  ->  Style (CSS) field
   STEP 1: paste the @import line below as the VERY FIRST line of the Style field.
   STEP 2: paste everything from "BEGIN OVERRIDE" to the end at the VERY END of the Style field.
   ===================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

/* ============================ BEGIN OVERRIDE ============================ */
:root{
  --sans:"Plus Jakarta Sans","Segoe UI",Inter,-apple-system,BlinkMacSystemFont,Roboto,Arial,sans-serif;
  --lx-g9:#0B2A1F; --lx-g8:#123D2C; --lx-g7:#1C5A42; --lx-gold:#C8A04A; --lx-gold-l:#E7CD8C;
  --lx-ink:#16251E; --lx-ink2:#3F5248; --lx-mute:#5E7067;
}
body{font-family:var(--sans)}

/* ---------- 1. Title bar: one thin row (~52px) ---------- */
.life-premium .rhead,.rhead{
  display:flex!important;align-items:center!important;flex-wrap:nowrap!important;
  min-height:0!important;height:52px!important;padding:0 16px!important;gap:12px!important;
  background:linear-gradient(110deg,var(--lx-g9),var(--lx-g8) 60%,var(--lx-g7))!important;
  border:0!important;border-bottom:1px solid var(--lx-gold)!important;box-shadow:0 2px 10px rgba(11,42,31,.18)!important;
}
.life-premium .life-homeback,.life-homeback{display:flex!important;align-items:center!important;gap:6px!important;flex:0 0 auto!important}
.life-homeback a,.life-homeback button{
  width:30px!important;height:30px!important;border-radius:8px!important;font-size:15px!important;
  border:1px solid rgba(231,205,140,.55)!important;color:var(--lx-gold-l)!important;background:rgba(255,255,255,.04)!important;
}
.life-homeback a:hover,.life-homeback button:hover{background:rgba(231,205,140,.14)!important}
/* "Branch requests" link: gold pill in the same row instead of stacked text */
.life-homeback #life-conversion-workspace-link{
  width:auto!important;height:30px!important;padding:0 12px!important;display:inline-flex!important;align-items:center!important;
  font:700 12.5px/1 var(--sans)!important;letter-spacing:.01em!important;white-space:nowrap!important;
  background:linear-gradient(145deg,var(--lx-gold-l),var(--lx-gold))!important;color:var(--lx-g9)!important;
  border:1px solid #8F6A22!important;border-radius:999px!important;margin-left:4px!important;text-decoration:none!important;
}
.life-homeback #life-conversion-workspace-link:hover{filter:brightness(1.05)}
.rhead .report-title-wrap{display:flex;align-items:center;min-width:0}
.life-premium .rhead h1,.rhead h1{
  margin:0!important;font:800 17px/1 var(--sans)!important;letter-spacing:.06em!important;color:#fff!important;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
