function discountStatus(d) {
    var s = statusKey(d.status);
    if (s === 'approved') return 'Process Completed';
    if (['rejected', 'expired', 'cancelled', 'canceled', 'stopped', 'failed'].indexOf(s) > -1) return 'Rejected';
    return 'Pending'
}

function discountLevelNumber(v) {
    var m = /L\s*([1-4])/i.exec(text(v));
    return m ? parseInt(m[1], 10) : 0
}

function discountStageRole(n) {
    return n === 1 ? 'Branch Level' : n === 2 ? 'Cluster Level' : n === 3 ? 'Corporate Level' : n === 4 ? 'MD / L4' : 'Discount Approval'
}

function discountRequestStageStatus(x) {
    var k = statusKey(x && x.status);
    if (k === 'approved') return 'Approved';
    if (['rejected', 'expired', 'cancelled', 'canceled', 'stopped', 'failed'].indexOf(k) > -1 || k.indexOf('reject') > -1) return 'Rejected';
    return 'Pending'
}

function discountHistoryUpToRequest(d, hist) {
    hist = hist || [];
    var cut = D(d && d.creation),
        cutMs = cut.getTime(),
        cur = text(d && d.name);
    return hist.filter(function(x) {
        if (!x) return false;
        if (text(x.name) === cur) return true;
        var xd = D(x.creation),
            xm = xd.getTime();
        if (!isFinite(cutMs) || !isFinite(xm)) return true;
        return xm <= cutMs
    }).sort(function(a, b) {
        return D(a.creation) - D(b.creation)
    })
}

function discountStagesForRequest(d, hist) {
    var rows = discountHistoryUpToRequest(d, hist),
        byLevel = {};
    rows.forEach(function(x) {
        var n = discountLevelNumber(x.approval_level);
        if (!n) return;
        // Keep the latest record for each level that existed by this request.
        byLevel[n] = x
    });
    // The current record must always be represented, even if history lookup was empty.
    var curLevel = discountLevelNumber(d && d.approval_level);
    if (curLevel && !byLevel[curLevel]) byLevel[curLevel] = d;
    var stages = [],
        extra = [];
    [1, 2, 3, 4].forEach(function(n) {
        var x = byLevel[n];
        if (!x) return;
        var st = discountRequestStageStatus(x);
        var person = st === 'Approved' || st === 'Rejected' ? (x.approved_by || x.selected_approver || x.requested_by) : (x.selected_approver || x.approved_by || x.requested_by);
        if (n === 4 && st === 'Pending') person = 'Final Management (KP / Bhuvan)';
        var at = st === 'Pending' ? null : (x.approved_at || x.modified || x.creation);
        var remark = x.rejection_reason || x.approver_note || x.reason || '';
        var stage = mkStage(n, discountStageRole(n), st, person, at, remark);
        if (n <= 3) stages.push(stage);
        else extra.push(stage)
    });
    return {
        stages: stages,
        extraStages: extra
    }
}
async function loadDiscountSiblingHistory(raw) {
    raw = raw || [];
    var invoices = [];
    raw.forEach(function(d) {
        var n = text(d && d.linked_invoice);
        if (n && invoices.indexOf(n) < 0) invoices.push(n)
    });
    if (!invoices.length) return;
    var rows = await safeList('Discount Approval Request',
        ['name', 'creation', 'modified', 'request_id', 'linked_invoice', 'branch', 'requested_by', 'approval_level', 'selected_approver', 'requested_discount_pct', 'proposed_final_amount', 'status', 'approved_discount_pct', 'approved_final_amount', 'approved_by', 'approved_at', 'approver_note', 'rejection_reason', 'reason'],
        [
            ['linked_invoice', 'in', invoices]
        ], 'creation asc', Math.max(100, invoices.length * 6), 'Discount approval chain');
    await enrichUserRefs(rows);
    var grouped = {};
    rows.forEach(function(x) {
        var k = text(x && x.linked_invoice);
        if (k)(grouped[k] = grouped[k] || []).push(x)
    });
    raw.forEach(function(d) {
        d.__discount_history = grouped[text(d.linked_invoice)] || []
    })
}

