function COLS(t) {
    var isAll = (t === 'ALL');
    var isStockTab = isStockReportType(t);
    var C = [];

    /* ---------------------------------------------------------
       SL NO.
    --------------------------------------------------------- */
    C.push({
        h: '#',
        sub: 'Sl',
        cls: 'c',
        w: '34px',
        nos: 1,

        sv: function(r) {
            return r.no;
        },

        td: function(r) {
            return '<span style="font-size:10.5px;color:#6A7C72;font-weight:700">' +
                r.no +
                '</span>';
        },

        x: [{
            h: 'Sl No',
            v: function(r) {
                return r.no;
            }
