            w: '96px',

            sv: function(r) {
                return reportTypeKey(r);
            },

            td: function(r) {
                var m = reportTypeMeta(r);
                var k = reportTypeKey(r);

                return two(
                    '<span class="tag ' + typTag(k) + '">' + m.short + '</span>',
                    m.name.length > 16 ? m.short + ' request' : m.name
                );
            },

            x: [{
                h: 'Approval Type',
                v: function(r) {
                    return reportTypeMeta(r).name;
                }
            }]
        });
    }


    /* ---------------------------------------------------------
       REQUEST ID
    --------------------------------------------------------- */
    C.push({
        h: 'Request ID',
        sub: 'Requested Date & Time',
        w: '166px',

        sv: function(r) {
            return r.reqDT;
        },

        td: function(r) {
            return two(
                '<span class="mono">' + esc(r.reqId) + '</span>',
                fmtDT(r.reqDT)
            );
        },

        x: [{
                h: 'Request ID',
                v: function(r) {
                    return r.reqId;
                }
            },
            {
                h: 'Request Date',
                v: function(r) {
