                    if (r.type === 'DISC') {
                        return r.gross;
                    }

                    return r.value;
                }
            },
            {
                h: 'Approved Value',
                v: function(r) {
                    return r.value;
                }
            },
            {
                h: 'Credit / Discount',
                v: function(r) {
                    return r.credit;
                }
            }
        ]
    });


    /* ---------------------------------------------------------
       OUTSTANDING AMOUNT — DISCOUNT TAB ONLY

       r.due comes from:
       Sales Invoice.outstanding_amount

       The x mapping automatically adds this field to:
       1. Excel export
