            },
            {
                h: 'Designation',
                v: function(r) {
                    return r.reqByDesig;
                }
            }
        ]
    });


    /* ---------------------------------------------------------
       STOCK WORKFLOW
    --------------------------------------------------------- */
    if (isStockTab) {
        C.push({
            h: 'Current Workflow / Approval',
            sub: 'Real ERPNext state · no artificial levels',
            w: '210px',

            sv: function(r) {
                return r.workflowState ||
                    r.priority ||
                    r.sourceStatus ||
                    '';
            },

            td: function(r) {
                return stockWorkflowCell(r);
            },

            x: [{
                    h: 'Document Type',
                    v: function(r) {
                        return stockSourceLabel(r);
                    }
                },
                {
                    h: 'Current Workflow / Status',
                    v: function(r) {
                        return r.workflowState ||
                            r.priority ||
                            r.sourceStatus ||
                            '';
                    }
                },
