                        return x.at ?
                            fmtDT(x.at) :
                            '';
                    }
                }
            ]
        });
    }


    /* ---------------------------------------------------------
       APPROVAL LEVELS
    --------------------------------------------------------- */
    else {
        var s1 = TYPES[t === 'ALL' ? 'P2P' : t].stages;

        /*
         * Discount has four approval levels.
         * Other approval types have three levels.
         */
        var maxApprovalLevels = (t === 'DISC' ? 4 : 3);

        for (var L = 1; L <= maxApprovalLevels; L++) {
            (function(L) {
                var stageHead = t === 'ALL' ? [
                        'Centre Manager',
                        'Audit Team',
                        'COO / Management'
                    ][L - 1] :
                    s1[L - 1];

                C.push({
                    h: 'Level ' + L + ' — ' + stageHead,
                    sub: 'Approved By · Date, Time · Time Taken',
                    w: '186px',

                    sv: function(r) {
                        var s = apprAt(r, L);

                        return s && s.at ?
                            s.at :
