                            h: 'L' + L + ' Date',
                            v: function(r) {
                                if (r.type === 'STK') {
                                    return '';
                                }

                                var s = apprAt(r, L);

                                return s && s.at ?
                                    fmtD(s.at) :
                                    '';
                            }
                        },
                        {
                            h: 'L' + L + ' Time',
                            v: function(r) {
                                if (r.type === 'STK') {
                                    return '';
                                }

                                var s = apprAt(r, L);

