var F = {
    from: '',
    to: '',
    branch: '',
    status: '',
    stage: '',
    req: '',
    apr: '',
    q: '',
    age: 'all',
    preset: 'l30'
};

function setPreset(p) {
    F.preset = p;
    var t = D(TODAY),
        from = null,
        to = iso(t);
    if (p === 'today') from = iso(t);
    else if (p === 'yest') {
        var y = new Date(D(TODAY) - 86400000);
        from = iso(y);
        to = iso(y)
    } else if (p === 'l7') from = iso(new Date(D(TODAY) - 6 * 86400000));
    else if (p === 'l30') from = iso(new Date(D(TODAY) - 29 * 86400000));
    else if (p === 'l90') from = iso(new Date(D(TODAY) - 89 * 86400000));
    else if (p === 'tm') {
        // LIFE business month: 6th -> 5th. Before the 6th, the active cycle began last month.
        var cmStart = t.getDate() >= 6 ?
            new Date(t.getFullYear(), t.getMonth(), 6) :
            new Date(t.getFullYear(), t.getMonth() - 1, 6);
        var cmEnd = new Date(cmStart.getFullYear(), cmStart.getMonth() + 1, 5);
        from = iso(cmStart);
        to = iso(cmEnd);
    } else if (p === 'lm') {
        // Previous LIFE business month: previous cycle's 6th -> following 5th.
        var activeStart = t.getDate() >= 6 ?
            new Date(t.getFullYear(), t.getMonth(), 6) :
            new Date(t.getFullYear(), t.getMonth() - 1, 6);
        var lmStart = new Date(activeStart.getFullYear(), activeStart.getMonth() - 1, 6);
        var lmEnd = new Date(activeStart.getFullYear(), activeStart.getMonth(), 5);
        from = iso(lmStart);
        to = iso(lmEnd);
    } else {
        from = '';
        to = ''
    }
    F.from = from || '';
    F.to = to || '';
    byId('f-from').value = F.from;
    byId('f-to').value = F.to;
}

function rows() {
    var out = DATA.slice(),
        C = COLS(TYPE),
        col = null;
    for (var i = 0; i < C.length; i++)
        if (C[i].h === SORT.k) col = C[i];
    if (col) out.sort(function(a, b) {
        var x = col.sv(a),
            y = col.sv(b);
        return (x > y ? 1 : x < y ? -1 : 0) * SORT.dir
    });
    else out.sort(function(a, b) {
        return D(b.reqDT) - D(a.reqDT)
    });
    return out
}

