function renderTabs() {
    var allowedTypes = visibleTypeOrder();
    var h = '',
        all = allowedTypes.reduce(function(s, t) {
            return s + (TOTALS[t] || 0)
        }, 0);
    h += '<a class="' + (TYPE === 'ALL' ? 'on' : '') + '" onclick="setType(\'ALL\')">◦ All Approvals <span class="n">' + all + '</span></a>';
    allowedTypes.forEach(function(t) {
        var c = TOTALS[t] || 0;
        h += '<a class="' + (TYPE === t ? 'on' : '') + '" onclick="setType(\'' + t + '\')">' + TYPES[t].name + ' <span class="n">' + c + '</span></a>'
    });
    byId('tsw').innerHTML = h;
}

function pendingStageFilterOptions(type) {
    if (type === 'P2P') return [
        { v: '1', l: 'Centre Manager' },
        { v: '2', l: 'Audit Team' },
        { v: '3', l: 'COO / Management' }
    ];
    if (type === 'DISC') return [
        { v: '1', l: 'L1 — Branch Level' },
        { v: '2', l: 'L2 — Cluster Level' },
        { v: '3', l: 'L3 — Corporate Level' },
        { v: '4', l: 'L4 — Final Management' }
    ];
    if (type === 'C2C') return [
        { v: '1', l: 'Centre Manager' },
        { v: '2', l: 'Audit Team' },
        { v: '3', l: 'COO / Management' }
    ];
    if (type === 'B2B') return [
        { v: '1', l: 'Branch Manager' },
        { v: '2', l: 'Audit Team' },
        { v: '3', l: 'COO / Management' }
    ];

    /* ---------- Purchase Order / Purchase Invoice workflow states ---------- */
    if (type === 'PO' || type === 'PI') {
        var known = type === 'PO'
            ? ['Draft', 'Pending Ops Approval', 'Approved', 'Rejected']
            : ['Draft', 'Pending Ops Approval', 'Pending from CEO', 'Approved', 'Rejected'];

        /* Add anything else seen on the current page so custom states
           don't silently disappear from the filter. */
        (DATA || []).forEach(function(r) {
            if (reportTypeKey(r) !== type) return;
            var wf = lifeWorkflowStateOf(r);
            if (wf && known.indexOf(wf) < 0) known.push(wf);
        });

        return known.map(function(s) { return { v: s, l: lifePiCooLabel(s, type === 'PI' ? 'Purchase Invoice' : 'Purchase Order') }; });
    }

    /* ---------- Material Request: no stage filter ---------- */
    if (isStockReportType(type)) return [];

    /* ---------- Everything else (including ALL): generic level list ---------- */
    return [
        { v: '1', l: 'First approval stage' },
        { v: '2', l: 'Second approval stage' },
        { v: '3', l: 'Third / final approval stage' },
        { v: '4', l: 'Discount L4 / final management' }
    ];
}

function refreshStageOptions() {
    var el = byId('f-stage');
    if (!el) return;

    var opts = pendingStageFilterOptions(TYPE);
    var cur = F.stage || el.value || '';
    var allowed = opts.some(function(o) { return o.v === cur; });
    if (!allowed) {
        cur = '';
        F.stage = '';
    }

    /* ---------- Material Request: still not applicable ---------- */
    if (TYPE === 'STK') {
        el.innerHTML = '<option value="">Not applicable for ' + esc(TYPES[TYPE].name) + '</option>';
        el.value = '';
        el.disabled = true;
        el.title = 'Material Request uses its ERPNext document status instead of a workflow state.';
        return;
    }

    /* ---------- Purchase Order / Purchase Invoice: real workflow states ---------- */
    if (TYPE === 'PO' || TYPE === 'PI') {
        el.disabled = false;
        el.title = 'Filter by the live ERPNext workflow state.';
        el.innerHTML = '<option value="">All Workflow States</option>' +
            opts.map(function(o) {
                return '<option value="' + esc(o.v) + '"' +
                       (cur === o.v ? ' selected' : '') + '>' +
                       esc(o.l) + '</option>';
            }).join('');
        el.value = cur;
        return;
    }

    /* ---------- Everything else: existing behaviour ---------- */
    el.disabled = false;
    el.title = 'Filter requests by the stage where they are currently pending / held.';
    el.innerHTML = '<option value="">All Pending Stages</option>' +
        opts.map(function(o) {
            return '<option value="' + esc(o.v) + '"' +
                   (cur === o.v ? ' selected' : '') + '>' +
                   esc(o.l) + '</option>';
        }).join('');
    el.value = cur;
}

function setType(t) {
    t = String(t || 'ALL');

    if (!canAccessReportType(t)) {
        TYPE = 'ALL';
        PAGE = 1;
        SORT = {
            k: 'Request ID',
            dir: -1
        };
        F.stage = '';
        renderTabs();
        refreshStageOptions();
        toast('Purchase Orders and Purchase Invoices are available only to System Manager or Stock Manager users.', 'err');
        refreshReport();
        return
    }

    TYPE = t;
    PAGE = 1;
    SORT = {
        k: 'Request ID',
        dir: -1
    };
    /* Pending-stage meanings differ by approval type, so do not carry an old stage selection into another tab. */
    F.stage = '';
    renderTabs();
    refreshStageOptions();
    refreshReport()
}

