function lifeSetStatsCollapsed(collapsed) {
    var wrap = byId('life-stats-collapse');
    var btn = byId('life-stats-toggle');
    if (!wrap || !btn) return;
    var open = !collapsed;
    wrap.classList.toggle('open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    var label = btn.querySelector('.life-stats-toggle-label');
    if (label) label.textContent = open ? 'Hide Stats & Summary' : 'Show Stats & Summary';
    btn.title = open ? 'Collapse stats and summary' : 'Expand stats and summary';
}

function lifeToggleStatsCollapse() {
    var wrap = byId('life-stats-collapse');
    if (!wrap) return;
    lifeSetStatsCollapsed(wrap.classList.contains('open'))
}

function lifeInstallStatsCollapse() {
    ensureLifeStatsCollapseStyles();
    var k = byId('kpis'),
        a = document.querySelector('.astrip');
    if (!k || !a) return;

    var existing = byId('life-stats-collapse');
    if (existing) {
        /* Keep the user's current open/closed state during report re-renders. */
        return
    }

    var parent = k.parentNode;
    if (!parent || a.parentNode !== parent) return;

    var toggleWrap = document.createElement('div');
    toggleWrap.className = 'life-stats-toggle-wrap noprint';
    toggleWrap.innerHTML = '<button type="button" id="life-stats-toggle" class="life-stats-toggle" aria-expanded="false" onclick="lifeToggleStatsCollapse()"><span class="life-stats-toggle-label">Show Stats & Summary</span><span class="life-stats-chevron">⌄</span></button>';

    var collapse = document.createElement('div');
    collapse.id = 'life-stats-collapse';
    collapse.className = 'life-stats-collapse';

    parent.insertBefore(toggleWrap, k);
    parent.insertBefore(collapse, k);
    collapse.appendChild(k);
    collapse.appendChild(a);

    /* Requirement: closed by default on every fresh page load. */
    lifeSetStatsCollapsed(true)
}

function kpis(list) {
    var done = list.filter(function(r) {
            return r.status === 'Process Completed'
        }),
        pend = list.filter(function(r) {
            return r.status === 'Pending'
        }),
        rej = list.filter(function(r) {
            return r.status === 'Rejected'
        }),
        val = list.reduce(function(s, r) {
            return s + r.value
        }, 0),
        cred = list.reduce(function(s, r) {
            return s + (r.credit || 0)
        }, 0),
        pval = pend.reduce(function(s, r) {
            return s + r.value
        }, 0),
        brc = pend.filter(function(r) {
            return tatH(r) > 168
        }).length,
        avg = done.length ? done.reduce(function(s, r) {
            return s + tatH(r)
        }, 0) / done.length : 0,
        fast = done.length ? Math.min.apply(null, done.map(function(r) {
            return tatH(r)
        })) : 0,
        totalLabel = (CURRENT_TOTAL === null ? (list.length + (HAS_NEXT ? '+' : '')) : CURRENT_TOTAL);
    var totalBreakup = '';

    if (TYPE === 'ALL') {
        totalBreakup =
            '<div class="life-kpi-type-breakup">' +
            '<div class="life-kpi-mini"><b>' + (TOTALS.P2P || 0) + '</b><span>P2P</span></div>' +
            '<div class="life-kpi-mini"><b>' + (TOTALS.DISC || 0) + '</b><span>DISC</span></div>' +
            '<div class="life-kpi-mini"><b>' + (TOTALS.C2C || 0) + '</b><span>C2C</span></div>' +
            '<div class="life-kpi-mini"><b>' + (TOTALS.B2B || 0) + '</b><span>B2B</span></div>' +
            '<div class="life-kpi-mini"><b>' + (TOTALS.STK || 0) + '</b><span>STOCK</span></div>' +
            (canAccessPurchaseTabs() ? '<div class="life-kpi-mini"><b>' + (TOTALS.PO || 0) + '</b><span>PO</span></div>' : '') +
            (canAccessPurchaseTabs() ? '<div class="life-kpi-mini"><b>' + (TOTALS.PI || 0) + '</b><span>PI</span></div>' : '') +
            '</div>';
    } else {
        totalBreakup = TYPES[TYPE].name + ' · selected period';
    }

    var t = [
        ['t-info', totalLabel, 'Total Requests', totalBreakup],
        ['t-ok', done.length, 'Fully Approved', 'Current page · ' + pct(done.length, list.length) + '%'],
        ['t-warn', pend.length, 'Pending Now', 'Current page · ' + moneyK(pval) + ' value'],
        ['t-crit', rej.length, 'Rejected', 'Current page · ' + brc + ' pending over 7 days'],
        ['t-gold', money(val), 'Approved Value', 'Current page value'],
        ['t-sp', money(cred), 'Credit / Discount', 'Current page value'],
        ['t-teal', avg ? hrsTxt(avg) : '—', 'Avg Approval Time', 'Current page · fastest ' + (fast ? hrsTxt(fast) : '—')]
    ];
    byId('kpis').innerHTML = t.map(function(x) {
        return '<div class="tile ' + x[0] + '"><div class="v tnum">' + x[1] + '</div><div class="k">' + x[2] + '</div><div class="d">' + x[3] + '</div></div>'
    }).join('');
}

function pct(a, b) {
    return b ? Math.round(a * 100 / b) : 0
}

function hrsTxt(h) {
    if (h >= 24) return (h / 24).toFixed(1) + ' days';
    if (h >= 1) return h.toFixed(1) + ' hrs';
    return Math.round(h * 60) + ' min'
}

function bars(el, map, onclick, cls) {
    var keys = Object.keys(map).sort(function(a, b) {
        return map[b] - map[a]
    });
    var max = Math.max.apply(null, keys.map(function(k) {
        return map[k]
    })) || 1;
    byId(el).innerHTML = keys.map(function(k) {
        return '<div class="hbar" onclick="' + onclick.replace('%K%', k.replace(/'/g, "")) + '">' +
            '<div class="lb">' + esc(k) + '</div><div class="tr"><i class="' + (cls || '') + '" style="width:' + (map[k] * 100 / max) + '%"></i></div>' +
            '<div class="vl tnum">' + map[k] + '</div></div>'
    }).join('') || '<div class="l2">No data</div>';
}

function feed(list) {
    var ev = [];
    list.forEach(function(r) {
        (r.stages || []).concat(r.extraStages || []).forEach(function(s) {
            if (s.at) ev.push({
                at: s.at,
                r: r,
                s: s
            })
        });
    });
    ev.sort(function(a, b) {
        return D(b.at) - D(a.at)
    });
    byId('a-feed').innerHTML = ev.slice(0, 40).map(function(e) {
        var ok = e.s.status === 'Approved';
        var subject = e.r.type === 'STK' ? (e.r.indent || e.r.reqId) : (e.r.client && e.r.client.name ? e.r.client.name : e.r.reqId);
