            '<div class="frow frow1">' +
            '<div class="fleft"><span class="fmain">' + esc(subject) + '</span><span class="ftype">· ' + esc(tm.short) + '</span><span class="freq">' + esc(e.r.reqId) + '</span></div>' +
            '<div class="fright fbranch">' + esc(e.r.branch || 'Branch not resolved') + '</div>' +
            '</div>' +
            '<div class="frow frow2">' +
            '<div class="fleft fapproval"><span class="fsub">' + (ok ? 'Approved' : 'Rejected') + ' by</span><span class="fperson">' + esc(e.s.person || 'Not recorded') + '</span><span class="frole">' + esc(role) + '</span></div>' +
            '<div class="fright fmeta"><span>' + fmtDT(e.s.at) + '</span><span> · ' + moneyK(e.r.value) + '</span><span class="fage"> · ' + ageTxt(e.at, TODAY) + ' ago</span></div>' +
