function lifeStopTableHoverScroll() {
    LIFE_TABLE_HSCROLL.dir = 0;
    LIFE_TABLE_HSCROLL.el = null;
    LIFE_TABLE_HSCROLL.last = 0;
    if (LIFE_TABLE_HSCROLL.raf) {
        cancelAnimationFrame(LIFE_TABLE_HSCROLL.raf);
        LIFE_TABLE_HSCROLL.raf = 0
    }
}

function lifeTableHoverScrollStep(ts) {
    var S = LIFE_TABLE_HSCROLL,
        el = S.el;
    if (!el || !S.dir) {
        lifeStopTableHoverScroll();
        return
    }
    if (!S.last) S.last = ts;
    var dt = Math.min(34, Math.max(8, ts - S.last));
    S.last = ts;
    el.scrollLeft += S.dir * (dt * .78);
    lifeUpdateTableHoverScrollEdges(el);
    var max = Math.max(0, el.scrollWidth - el.clientWidth);
    if ((S.dir < 0 && el.scrollLeft <= 1) || (S.dir > 0 && el.scrollLeft >= max - 1)) {
        lifeStopTableHoverScroll();
        return
    }
    S.raf = requestAnimationFrame(lifeTableHoverScrollStep)
}

function lifeStartTableHoverScroll(el, dir) {
    if (!el || !(el.scrollWidth > el.clientWidth + 4)) return;
    if (dir < 0 && el.scrollLeft <= 1) return;
    var max = Math.max(0, el.scrollWidth - el.clientWidth);
    if (dir > 0 && el.scrollLeft >= max - 1) return;
    lifeStopTableHoverScroll();
    LIFE_TABLE_HSCROLL.el = el;
    LIFE_TABLE_HSCROLL.dir = dir < 0 ? -1 : 1;
    LIFE_TABLE_HSCROLL.raf = requestAnimationFrame(lifeTableHoverScrollStep)
}

function lifeEnsureMainTableHorizontalWidth(el) {
    if (!el) return;
    var table = el.querySelector('#tbl');
    if (!table) return;
    var heads = table.querySelectorAll('thead th').length;
    if (!heads) return;

    /* Keep each approvals-report column readable instead of letting the browser
       squeeze every column into the available viewport. */
    var perColumn = heads >= 12 ? 128 : (heads >= 9 ? 138 : 148);
    var wanted = Math.max(el.clientWidth, heads * perColumn);
    table.style.minWidth = wanted + 'px';
    table.style.width = 'max-content';
}

function lifeUpdateTableHoverScrollEdges(el) {
    if (!el) return;
    var host = el.closest('.life-hscroll-host');
    if (!host) return;
    lifeEnsureMainTableHorizontalWidth(el);
    var max = Math.max(0, el.scrollWidth - el.clientWidth),
        has = max > 4;
    host.classList.toggle('life-has-overflow', has);
    var left = host.querySelector('.life-hscroll-btn.left');
    var right = host.querySelector('.life-hscroll-btn.right');
    if (left) {
        var atLeft = !has || el.scrollLeft <= 1;
        left.classList.toggle('life-edge', atLeft);
        left.disabled = atLeft
    }
    if (right) {
        var atRight = !has || el.scrollLeft >= max - 1;
        right.classList.toggle('life-edge', atRight);
        right.disabled = atRight
    }
}

function lifeTableScrollByViewport(el, dir) {
    if (!el) return;
    var amount = Math.max(300, Math.round(el.clientWidth * .76));
    try {
        el.scrollBy({
            left: (dir < 0 ? -amount : amount),
            behavior: 'smooth'
        })
    } catch (e) {
        el.scrollLeft += (dir < 0 ? -amount : amount)
    }
    setTimeout(function() {
        lifeUpdateTableHoverScrollEdges(el)
    }, 360)
}

function lifeInstallTableHoverScroll() {
    ensureLifeTableHoverScrollStyles();
    var el = document.querySelector('.tw');
    if (!el) return;

    var host = el.closest('.life-hscroll-host');
    if (!host) {
        host = document.createElement('div');
        host.className = 'life-hscroll-host';
        el.parentNode.insertBefore(host, el);
        host.appendChild(el);

        var left = document.createElement('button');
        left.type = 'button';
        left.className = 'life-hscroll-btn left';
        left.innerHTML = '‹';
        left.setAttribute('aria-label', 'Scroll table left');
        left.title = 'Hover to scroll left';

        var right = document.createElement('button');
        right.type = 'button';
        right.className = 'life-hscroll-btn right';
        right.innerHTML = '›';
        right.setAttribute('aria-label', 'Scroll table right');
        right.title = 'Hover to scroll right';

        host.appendChild(left);
        host.appendChild(right);

        left.addEventListener('mouseenter', function() {
            lifeStartTableHoverScroll(el, -1)
        });
        right.addEventListener('mouseenter', function() {
            lifeStartTableHoverScroll(el, 1)
        });
        left.addEventListener('mouseleave', lifeStopTableHoverScroll);
        right.addEventListener('mouseleave', lifeStopTableHoverScroll);
        left.addEventListener('blur', lifeStopTableHoverScroll);
        right.addEventListener('blur', lifeStopTableHoverScroll);
        left.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            lifeTableScrollByViewport(el, -1)
        });
        right.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            lifeTableScrollByViewport(el, 1)
        });
        el.addEventListener('scroll', function() {
            lifeUpdateTableHoverScrollEdges(el)
        }, {
            passive: true
        })
    }

    lifeEnsureMainTableHorizontalWidth(el);
    lifeUpdateTableHoverScrollEdges(el);

    /* ERPNext/Web Page layout can settle a little after render. Re-check twice
       so the controls do not disappear because of an early zero/temporary width. */
    setTimeout(function() {
        lifeEnsureMainTableHorizontalWidth(el);
        lifeUpdateTableHoverScrollEdges(el)
    }, 120);
    setTimeout(function() {
        lifeEnsureMainTableHorizontalWidth(el);
        lifeUpdateTableHoverScrollEdges(el)
    }, 500);

    if (!LIFE_TABLE_HSCROLL.resizeBound) {
        LIFE_TABLE_HSCROLL.resizeBound = true;
        window.addEventListener('resize', function() {
            var t = document.querySelector('.tw');
            if (t) {
                lifeEnsureMainTableHorizontalWidth(t);
                lifeUpdateTableHoverScrollEdges(t)
            }
        }, {
            passive: true
        })
    }
}

