function aggregatePOLines(pos) {
    var m = {};
    (pos || []).forEach(function(po) {
        (po.items || []).forEach(function(x) {
            var k = text(x.item_code || x.item_name);
            if (!k) return;
            if (!m[k]) m[k] = {
                item: text(x.item_name || x.item_code),
                qty: 0,
                amount: 0,
                rate: 0
            };
            m[k].qty += num(x.qty || x.stock_qty);
            m[k].amount += num(x.amount || num(x.rate) * num(x.qty));
        })
    });
    Object.keys(m).forEach(function(k) {
        m[k].rate = m[k].qty ? m[k].amount / m[k].qty : 0
    });
    return m
}

function piPOComparisonHTML(r) {
    if (r.stockSource !== 'Purchase Invoice' || !(r.linkedPOs || []).length) return '';
    var po = aggregatePOLines(r.linkedPOs),
        rows = (r.lines || []).map(function(x) {
            var key = '',
                p = null;
            Object.keys(po).some(function(k) {
                if (normBranchKey(k) === normBranchKey(x.item)) {
                    key = k;
                    p = po[k];
                    return true
                }
                return false
            });
            if (!p) {
                Object.keys(po).some(function(k) {
                    if (text(po[k].item) === text(x.item)) {
                        key = k;
                        p = po[k];
                        return true
                    }
                    return false
                });
            }
            var dq = p ? x.qty - p.qty : x.qty,
                dr = p ? x.rate - p.rate : x.rate,
                flag = !p || Math.abs(dq) > .0001 || Math.abs(dr) > .01;
            return '<tr' + (flag ? ' class="life-approval-diff"' : '') + '><td><b>' + esc(x.item) + '</b>' + (flag ? '<div class="life-approval-warn">Review difference</div>' : '') + '</td>' +
                '<td class="c tnum">' + (p ? p.qty : '—') + '</td><td class="c tnum">' + x.qty + '</td>' +
                '<td class="r tnum">' + (p ? money(p.rate) : '—') + '</td><td class="r tnum">' + money(x.rate) + '</td>' +
                '<td class="r tnum">' + (p ? money(dr) : '—') + '</td></tr>'
        }).join('');
    return '<div class="sec"><b>PO vs Purchase Invoice Check</b><i></i></div><div class="box" style="padding:0;overflow:hidden">' +
        '<table class="dt"><thead><tr><th>Item</th><th class="c">PO Qty</th><th class="c">PI Qty</th><th class="r">PO Rate</th><th class="r">PI Rate</th><th class="r">Rate Difference</th></tr></thead><tbody>' +
        rows + '</tbody></table></div>'
}

/* =========================================================================
   PURCHASE INVOICE — APPROVAL DETAIL VIEW
   Uses the complete Purchase Invoice already loaded into r.raw.
   ========================================================================= */

function piMoney(v, currency) {
    var n = num(v);
    var cur = text(currency, 'INR');

    var amount = n.toLocaleString('en-IN', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });

    return cur === 'INR' ?
        '₹' + amount :
        esc(cur) + ' ' + amount;
}

function piPlainText(v) {
    v = text(v);
    if (!v) return '—';

    return v
        .replace(/<br\s*\/?\s*>/gi, ' · ')
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;/gi, ' ')
        .replace(/\s+/g, ' ')
        .trim() || '—';
}

function piUnique(arr) {
    var out = [];

    (arr || []).forEach(function(v) {
        v = text(v);
        if (v && out.indexOf(v) < 0) out.push(v);
    });

    return out;
}

function piDocStatus(d) {
    d = d || {};

    if (num(d.docstatus) === 1) return 'Submitted';
    if (num(d.docstatus) === 2) return 'Cancelled';

    return text(d.status, 'Draft');
}

function piGstText(x) {
    x = x || {};

    var p = [];

    if (num(x.cgst_rate)) {
        p.push('CGST ' + num(x.cgst_rate) + '%');
    }

    if (num(x.sgst_rate)) {
        p.push('SGST ' + num(x.sgst_rate) + '%');
    }

    if (num(x.igst_rate)) {
        p.push('IGST ' + num(x.igst_rate) + '%');
    }

    if (num(x.cess_rate)) {
        p.push('Cess ' + num(x.cess_rate) + '%');
    }

    return p.join(' + ') || text(x.gst_treatment, 'Nil / 0%');
}


