/* ---------- HSN / GST BREAKUP ---------- */

function piTaxBreakupHTML(r) {

    var d = r.raw || {};
    var items = d.items || [];
    var currency = text(d.currency, 'INR');

    var grouped = {};

    items.forEach(function(x) {

        var hsn = text(x.gst_hsn_code, '—');

        var cgstRate = num(x.cgst_rate);
        var sgstRate = num(x.sgst_rate);
        var igstRate = num(x.igst_rate);
        var cessRate = num(x.cess_rate);

        var key = [
            hsn,
            cgstRate,
            sgstRate,
            igstRate,
            cessRate
        ].join('|');

        if (!grouped[key]) {
            grouped[key] = {
                hsn: hsn,

                cgstRate: cgstRate,
                sgstRate: sgstRate,
                igstRate: igstRate,
                cessRate: cessRate,

                taxable: 0,

                cgst: 0,
                sgst: 0,
                igst: 0,
                cess: 0
            };
        }

        var g = grouped[key];

        g.taxable += num(
            x.taxable_value ||
            x.net_amount ||
            x.amount
        );

        g.cgst += num(x.cgst_amount);
        g.sgst += num(x.sgst_amount);
        g.igst += num(x.igst_amount);

        g.cess +=
            num(x.cess_amount) +
            num(x.cess_non_advol_amount);

    });

    var rows = Object.keys(grouped).map(function(k) {

        var g = grouped[k];

        var totalTax =
            g.cgst +
            g.sgst +
            g.igst +
            g.cess;

        return '' +
            '<tr>' +

            '<td><b>' + esc(g.hsn) + '</b></td>' +

            '<td class="r tnum">' +
            piMoney(g.taxable, currency) +
            '</td>' +

            '<td class="r tnum">' +
            (g.cgstRate ? g.cgstRate + '% · ' : '') +
            piMoney(g.cgst, currency) +
            '</td>' +

            '<td class="r tnum">' +
            (g.sgstRate ? g.sgstRate + '% · ' : '') +
            piMoney(g.sgst, currency) +
            '</td>' +

            '<td class="r tnum">' +
            (g.igstRate ? g.igstRate + '% · ' : '') +
            piMoney(g.igst, currency) +
            '</td>' +

            '<td class="r tnum">' +
            (g.cessRate ? g.cessRate + '% · ' : '') +
            piMoney(g.cess, currency) +
            '</td>' +

            '<td class="r tnum">' +
            '<b>' + piMoney(totalTax, currency) + '</b>' +
            '</td>' +

            '</tr>';

    }).join('');

    if (!rows) {

        rows =
            '<tr>' +
            '<td colspan="7" class="empty" style="padding:18px">' +
            'No item-level GST breakup is recorded.' +
            '</td>' +
            '</tr>';

    }

    return '' +

        '<div class="sec">' +
        '<b>GST / HSN Breakup</b>' +
        '<i></i>' +
        '</div>' +

        '<div class="box" style="padding:0;overflow:auto">' +

        '<table class="dt">' +

        '<thead>' +
        '<tr>' +
        '<th>HSN / SAC</th>' +
        '<th class="r">Taxable Value</th>' +
        '<th class="r">CGST</th>' +
        '<th class="r">SGST</th>' +
        '<th class="r">IGST</th>' +
        '<th class="r">Cess</th>' +
        '<th class="r">Total Tax</th>' +
        '</tr>' +
        '</thead>' +

        '<tbody>' + rows + '</tbody>' +

        '</table>' +

        '</div>';
}


