        var prior = num(r.priorApprovedPct),
            cur = num(raw.requested_discount_pct || r.discPct),
            after = prior + cur,
            curAmt = r.gross * (cur / 100);
        h += kvCard('Approval Level', esc(text(raw.approval_level, '—')) + ' · ' + esc(discountLevelLabel(raw.approval_level)));
        h += kvCard('Original Bill', money(r.gross), 'Already approved ' + prior + '% · ' + money(r.priorApprovedAmount || 0));
        h += kvCard('Current Request', cur + '% · ' + money(curAmt), 'After approval ' + after + '%');
        h += kvCard('Expected Payable', money(r.net), 'Selected approver ' + esc(cleanUser(raw.selected_approver) || 'Not fixed'));
        h += '</div><div class="sec"><b>Discount Approval History</b><i></i></div>' + discountHistoryHTML(r);
        return h
    }
    if (r.type === 'STK' && r.stockSource === 'Purchase Order') {
        h += kvCard('Supplier', esc(r.vendor), esc(r.supplier || ''));
        h += kvCard('PO / Schedule Date', fmtD(r.poDate) + ' / ' + fmtD(r.scheduleDate), esc(r.company || ''));
        h += kvCard('Warehouse', esc(r.toWarehouse || r.fromWarehouse || '—'), 'Linked MR: ' + esc((r.linkedMaterialRequests || []).join(', ') || '—'));
        h += kvCard('Commercial Value', money(r.value), 'Net ' + money(r.netTotal || 0) + ' · Tax ' + money(r.taxAmount || 0));
        h += '</div>' + (r.remarks ? '<div class="life-decision-remarks"><b>PO Remarks</b><div>' + esc(r.remarks) + '</div></div>' : '');
        return h
    }
    if (r.type === 'STK' && r.stockSource === 'Purchase Invoice') {
        h += kvCard('Supplier / Bill', esc(r.vendor), esc(r.supplierBill || '—') + ' · ' + fmtD(r.supplierBillDate));
        h += kvCard('Posting / Due Date', fmtD(r.postingDate) + ' / ' + fmtD(r.dueDate), esc(r.payablesBranch || r.branch || ''));
