var LIFE_CONV_SIGNATURE_DATA = '';

function initLifeApprovalSignaturePad() {
    LIFE_CONV_SIGNATURE_DATA = '';
    var c = byId('life-conv-signature');
    if (!c) return;
    var ctx = c.getContext('2d'),
        drawing = false,
        last = null;

    function pos(ev) {
        var r = c.getBoundingClientRect(),
            p = ev.touches && ev.touches[0] ? ev.touches[0] : ev;
        return {
            x: (p.clientX - r.left) * (c.width / r.width),
            y: (p.clientY - r.top) * (c.height / r.height)
        }
    }

    function start(ev) {
        drawing = true;
        last = pos(ev);
        ev.preventDefault()
    }

    function move(ev) {
        if (!drawing) return;
        var p = pos(ev);
        ctx.beginPath();
        ctx.moveTo(last.x, last.y);
        ctx.lineTo(p.x, p.y);
        ctx.lineWidth = 2.2;
        ctx.lineCap = 'round';
        ctx.strokeStyle = '#173d2b';
        ctx.stroke();
        last = p;
        LIFE_CONV_SIGNATURE_DATA = c.toDataURL('image/png');
        var st = byId('life-conv-sign-status');
        if (st) st.textContent = 'Signature captured';
        ev.preventDefault()
    }

    function stop() {
        drawing = false;
        last = null
    }
    c.addEventListener('mousedown', start);
    c.addEventListener('mousemove', move);
    window.addEventListener('mouseup', stop);
    c.addEventListener('touchstart', start, {
        passive: false
    });
    c.addEventListener('touchmove', move, {
        passive: false
    });
    c.addEventListener('touchend', stop, {
        passive: false
    })
}

function lifeConvClearSignature() {
    var c = byId('life-conv-signature');
    if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
