    h += '<div class="sec"><b>Approval Chain</b><i></i><span class="cnt">' + (r.type === 'STK' ? (r.stages.filter(function(s) {
        return s.status === 'Approved'
    }).length + ' approved step(s)') : (r.stages.filter(function(s) {
        return s.status === 'Approved'
    }).length + ' of 3 cleared')) + '</span></div>';
    h += '<div class="chain">';
    for (var L = 1; L <= 3; L++) {
        var s = apprAt(r, L);
        var role = (s ? s.role : TYPES[r.type].stages[L - 1]);
        if (!s) h += '<div class="st"><div class="rl">Level ' + L + ' \u00b7 ' + role + '</div><div class="pn" style="color:#95A39B">Not reached</div><div class="dt">\u2014</div></div>';
        else if (s.status === 'Pending') h += '<div class="st wait"><div class="rl">Level ' + L + ' \u00b7 ' + role + '</div><div class="pn">\u23F3 Awaiting ' + esc(s.person) + '</div><div class="dt">Waiting ' + approvalDuration(prevAt(r, L), TODAY) + '</div></div>';
        else if (s.status === 'Rejected') h += '<div class="st no"><div class="rl">Level ' + L + ' \u00b7 ' + role + '</div><div class="pn">\u2716 ' + esc(s.person) + ' \u00b7 Rejected</div><div class="dt">' + fmtDT(s.at) + ' \u00b7 took ' + approvalDuration(prevAt(r, L), s.at) + '</div></div>';
        else h += '<div class="st done"><div class="rl">Level ' + L + ' \u00b7 ' + role + '</div><div class="pn">\u2714 ' + esc(s.person) + '</div><div class="dt">' + fmtDT(s.at) + ' \u00b7 took ' + approvalDuration(prevAt(r, L), s.at) + '</div></div>';
    }
    h += '</div>';
    if (r.extraStages && r.extraStages.length) {
        h += '<div class="sec"><b>Additional Workflow Step</b><i></i></div><div class="chain">';
        r.extraStages.forEach(function(x) {
            h += '<div class="st ' + (x.status === 'Approved' ? 'done' : x.status === 'Rejected' ? 'no' : 'wait') + '"><div class="rl">' + esc(x.role) + '</div><div class="pn">' + (x.status === 'Approved' ? '✔ ' : x.status === 'Rejected' ? '✖ ' : '⏳ ') + esc(x.person || x.role) + ' · ' + esc(x.status) + '</div><div class="dt">' + (x.at ? fmtDT(x.at) : 'time not recorded') + '</div></div>'
        });
        h += '</div>';
    }

    /* info grid */
    h += '<div class="sec"><b>Request Information</b><i></i></div><div class="g3">';
    if (r.type !== 'STK') {
        h += '<div class="box"><div class="hd">Client</div>' +
            kv('Name', esc(r.client.name)) + kv('Mobile', mob(r.client.mobile)) + kv('Gender &amp; Age', gIcon(r.client.gender) + ' ' + r.client.gender + ' \u00b7 ' + r.client.age + ' yrs') +
            kv('Client Code', r.client.code) + kv('Client With Us From', fmtD(r.client.since) + ' (' + ageTxt(r.client.since, TODAY) + ')') + '</div>';
    } else {
        h += '<div class="box"><div class="hd">Stock / Purchase Document</div>' + kv('Document Type', esc(stockSourceLabel(r))) + kv(r.stockSource === 'Material Request' ? 'Vendor / Source' : 'Supplier', esc(r.vendor)) + kv('Contact', mob(r.vendorPh)) +
            kv('Document No', esc(r.reqId)) + kv('Workflow / Status', esc(r.workflowState || r.priority)) + kv('Items / Qty', r.items + ' items · ' + r.qty) +
            (r.supplierBill ? kv('Supplier Bill', esc(r.supplierBill) + (r.supplierBillDate ? ' · ' + fmtD(r.supplierBillDate) : '')) : '') + '</div>';
    }
    h += '<div class="box"><div class="hd">Branch &amp; Staff</div>' + kv('Branch', esc(r.branch)) +
        kv(r.type === 'STK' ? 'Raised By' : 'Booked By', esc(r.bookedBy)) + kv('Requested By', esc(r.reqBy)) +
        kv('Designation', esc(r.reqByDesig)) + kv('Login / Email', esc(r.reqByEmail)) + '</div>';
    h += '<div class="box"><div class="hd">Timing</div>' + kv('Request Date &amp; Time', fmtDT(r.reqDT)) +
        kv('Level 1 Time Taken', apprAt(r, 1) && apprAt(r, 1).at ? approvalDuration(r.reqDT, apprAt(r, 1).at) : '\u2014') +
        kv('Level 2 Time Taken', apprAt(r, 2) && apprAt(r, 2).at ? approvalDuration(prevAt(r, 2), apprAt(r, 2).at) : '\u2014') +
        kv('Level 3 Time Taken', apprAt(r, 3) && apprAt(r, 3).at ? approvalDuration(prevAt(r, 3), apprAt(r, 3).at) : '\u2014') +
        kv('Total Turnaround', '<b class="' + (tatH(r) > 168 ? 'aged' : '') + '">' + ageTxt(r.reqDT, doneAt(r) || TODAY) + '</b>') + '</div>';
    h += '</div>';

    /* detail tables */
    /* detail tables */
    if (r.type === 'P2P') {

        h += p2pWebPageDetailHTML(r);

    } else if (r.type === 'C2C') {

        h += c2cWebPageDetailHTML(r);

    } else if (
        r.type === 'STK' &&
        r.stockSource === 'Purchase Invoice'
    ) {

        // Purchase Invoice gets its own complete approval-ready view.
        h += purchaseInvoiceDetailHTML(r);

    } else {

        h += '<div class="sec"><b>' +
            (
                r.type === 'DISC' ?
                'Billing Breakup' :
                r.type === 'STK' ?
                stockSourceLabel(r) + ' Line Items' :
                'Transfer Breakup'
            ) +
            '</b><i></i></div>';

        h += '<div class="box" style="padding:0;overflow:hidden">' +
            detTable(r) +
            '</div>';
    }

    /* documents */
    h += '<div class="sec"><b>Supporting Documents</b><i></i><span class="cnt">' + (r.docs || []).length + ' files</span></div>';
    if (r.docs && r.docs.length) {
        h += '<div class="box" style="padding:0;overflow:hidden"><table class="dt"><thead><tr><th style="width:44px">No.</th><th>Document Name</th><th class="c" style="width:88px">Mandatory</th><th>File</th><th class="c" style="width:78px">Type</th><th>Remarks</th></tr></thead><tbody>' +
            r.docs.map(function(d, i) {
                var visibleName = d.fileName || ((d.file || '').split('?')[0].split('/').pop()) || 'Open File';
                var link = d.file ? '<a class="docl" href="' + esc(d.file) + '" target="_blank" rel="noopener">' + esc(visibleName) + '</a>' : '<span class="life-muted">No file URL stored</span>';
                return '<tr><td class="c">' + (i + 1) + '</td><td><b>' + esc(d.name) + '</b></td><td class="c">' + (d.mandatory ? 'Yes' : 'No') + '</td><td>' + link + '</td><td class="c">' + esc(d.type || '—') + '</td><td>' + esc(d.remarks || '—') + '</td></tr>'
            }).join('') + '</tbody></table></div>';
    } else h += '<div class="box"><span class="life-muted">No supporting documents are stored on this request.</span></div>';

    /* timeline */
    h += '<div class="sec"><b>Approval Timeline</b><i></i></div>';
    h += '<div class="box"><div class="tline">';
    h += '<div class="ev"><b>\uD83D\uDCDD Request Submitted</b><div class="rm"><em>Request:</em>' + esc(detTop(r)) + ' \u2014 ' + money(r.value) + '</div>' +
        '<div class="by"><b>' + esc(r.reqByEmail) + '</b> <span class="tag t-b">Submitted</span> \u00b7 ' + fmtDT(r.reqDT) + '</div></div>';
    r.stages.concat(r.extraStages || []).forEach(function(s, i) {
        var who = esc(s.person || s.role || '');
        if (s.status === 'Pending') {
            var ps = prevAt(r, s.lvl),
                exactPendingStart = ps && hasExactClockTime(ps),
                wait = exactPendingStart ? ageTxt(ps, TODAY) : 'time not recorded',
                breach = exactPendingStart ? hrs(ps, TODAY) > 168 : false;
            h += '<div class="ev w"><b>\u23F3 ' + esc(s.role) + ' \u2014 Awaiting ' + who + '</b>' +
                '<div class="by">' + (ps ? 'Pending since ' + approvalTimeDisplay(ps) + ' \u00b7 ' : '') + '<b class="' + (breach ? 'aged' : 'pend-i') + '">' + (exactPendingStart ? 'waiting ' : '') + wait + '</b></div></div>';
        } else {
            var rj = s.status === 'Rejected',
                taken = s.at ? approvalDuration(prevAt(r, s.lvl), s.at) : 'time not recorded';
            h += '<div class="ev' + (rj ? ' r' : '') + '"><b>' + (rj ? '\u2716' : '\u2714') + ' ' + esc(s.role) + ' \u2014 ' + (rj ? 'Rejected' : 'Approved') + ' by ' + who + '</b>' +
                '<div class="rm"><em>Remarks:-</em>' + esc(s.remark || '—') + '</div>' +
                '<div class="by"><b>' + who + '</b> <span class="tag ' + (rj ? 't-r' : 't-g') + '">' + s.status + '</span> \u00b7 ' + approvalTimeDisplay(s.at) +
                ' <span style="color:#95A39B">[' + taken + ']</span></div></div>';
        }
    });
    if (r.status === 'Process Completed')
        h += '<div class="ev"><b>\uD83C\uDFC1 Process Completed</b><div class="rm">Process Completed.</div>' +
        '<div class="by"><b>System</b> <span class="tag t-g">Completed</span> \u00b7 ' + fmtDT(doneAt(r)) + '</div></div>';
    h += '</div></div>';

    /* guarded action area: P2P + C2C + B2B + Discount + PO + PI */
    h += approvalActionHTML(r);
    return h;
}

