function lifeSalesInvoicePrintUrl(invoiceName) {
    invoiceName = String(invoiceName || '').trim();
    if (!invoiceName) return '';
    return window.location.origin + '/printview?doctype=' + encodeURIComponent('Sales Invoice') + '&name=' + encodeURIComponent(invoiceName) + '&format=' + encodeURIComponent(LIFE_SALES_INVOICE_PRINT_FORMAT) + '&no_letterhead=0'
}

function lifeCloseSalesInvoiceModal() {
    var m = document.getElementById('lifeSalesInvoiceViewer');
    if (m && m.parentNode) m.parentNode.removeChild(m)
}

function lifeOpenSalesInvoiceModal(event, invoiceName) {
    if (event) {
        event.preventDefault();
        event.stopPropagation()
    }
    invoiceName = String(invoiceName || '').trim();
    if (!invoiceName) return;
    ensureLifeInvoiceViewerStyles();
    lifeCloseSalesInvoiceModal();
    var url = lifeSalesInvoicePrintUrl(invoiceName);
    if (!url) return;
    var wrap = document.createElement('div');
    wrap.id = 'lifeSalesInvoiceViewer';
    wrap.className = 'life-invoice-viewer';
    wrap.innerHTML = '<div class="life-invoice-viewer-dialog" role="dialog" aria-modal="true" aria-label="Sales Invoice Bill">' +
        '<div class="life-invoice-viewer-head"><div><div class="life-invoice-viewer-title">Sales Invoice Bill</div><div class="life-invoice-viewer-sub">' + esc(invoiceName) + '</div></div><div class="life-invoice-viewer-sp"></div><button type="button" class="life-invoice-viewer-close" aria-label="Close invoice">&times;</button></div>' +
        '<div class="life-invoice-viewer-body"><div class="life-invoice-viewer-load">Loading ' + esc(invoiceName) + '...</div><iframe class="life-invoice-viewer-frame" src="' + esc(url) + '" title="Sales Invoice ' + esc(invoiceName) + '"></iframe></div></div>';
    document.body.appendChild(wrap);
    wrap.addEventListener('click', function(e) {
        if (e.target === wrap || e.target.closest('.life-invoice-viewer-close')) lifeCloseSalesInvoiceModal()
    });
    var iframe = wrap.querySelector('.life-invoice-viewer-frame'),
        loader = wrap.querySelector('.life-invoice-viewer-load');
    if (iframe) iframe.addEventListener('load', function() {
        if (loader) loader.style.display = 'none';
        try {
            var d = iframe.contentDocument || iframe.contentWindow.document;
            if (!d) return;
            var a = d.querySelector('.action-banner');
            if (a) a.remove();
            var g = d.querySelector('.print-format-gutter');
            if (g) g.style.paddingTop = '20px'
        } catch (err) {
            ('Unable to clean invoice print toolbar:', err, void 0)
        }
    })
}

function lifeInvoiceAnchor(name, label) {
    name = String(name || '').trim();
    if (!name) return esc(label || '\u2014');
    return '<a href="#" class="life-invoice-modal-link" onclick="lifeOpenSalesInvoiceModal(event,\'' + lifeInvoiceJsValue(name) + '\')">' + esc(label || name) + '</a>'
}

function invoicePillHTML(r) {
    var rows = r.invoiceRows || [];
    if (rows.length) {
        var links = rows.map(function(x) {
            var label = x.name + (x.date ? ' \u00b7 ' + fmtD(x.date) : '');
            return lifeInvoiceAnchor(x.name, label)
        }).join(' &nbsp;/&nbsp; ');
        return '<span class="pill">Invoice' + (rows.length > 1 ? 's' : '') + ': <b>' + links + '</b></span>'
    }
    var inv = String(r.invoice || '').trim();
    if (inv) {
        var names = inv.split(/[,;\n]+/).map(function(x) {
            return String(x || '').trim()
        }).filter(Boolean);
        var links = names.map(function(name, idx) {
            return lifeInvoiceAnchor(name, name + (idx === 0 && r.invoiceDT ? ' \u00b7 ' + fmtD(r.invoiceDT) : ''))
        }).join(' &nbsp;/&nbsp; ');
        return '<span class="pill">Invoice' + (names.length > 1 ? 's' : '') + ': <b>' + links + '</b></span>'
    }
    return '<span class="pill">Invoice: <b>\u2014</b></span>'
}

