function p2pPackageService(row) {
    row = row || {};
    return text(first(row, ['converted_package__service_name', 'service_package_name', 'therapy_type', 'service_name', 'package_name', 'item_name', 'item_code'], 'Therapy / Package'))
}

function p2pPackageQty(row) {
    return num(first(row || {}, ['converted_quantity', 'no_of_sessions', 'qty', 'quantity', 'sessions'], 0))
}

function p2pPackageAmount(row) {
    var x = row || {},
        amount = num(first(x, ['balance_amount', 'amount', 'total_amount', 'package_value', 'value'], 0));
    if (!amount) {
        var q = p2pPackageQty(x),
            rate = num(first(x, ['rate', 'price', 'per_session', 'per_session_value'], 0));
        if (q && rate) amount = q * rate
    }
    return Math.round(amount * 100) / 100
}

function p2pPackageRate(row) {
    var q = p2pPackageQty(row),
        amount = p2pPackageAmount(row),
        stored = num(first(row || {}, ['rate', 'price', 'per_session', 'per_session_value'], 0));
    return q ? amount / q : stored
}

function p2pPackageRows(rows) {
    return (rows || []).map(function(row) {
        return {
            therapy: p2pPackageService(row),
            qty: p2pPackageQty(row),
            amount: p2pPackageAmount(row),
            rate: p2pPackageRate(row),
            sourcePlan: text(first(row || {}, ['source_plan', 'source_therapy_plan', 'therapy_plan']))
        }
    }).filter(function(row) {
        return !!row.therapy && (row.qty > 0 || row.amount > 0)
    })
}

function p2pPackageRowsKey(rows) {
    return JSON.stringify(p2pPackageRows(rows).map(function(row) {
        return [text(row.therapy).toLowerCase(), num(row.qty), Math.round(num(row.amount) * 100) / 100]
    }).sort())
}

function p2pBranchRequestedRows(doc) {
