function p2pPackageVersionHistoryHTML(r) {
    var d = r.raw || {},
        branch = p2pBranchRequestedRows(d),
        audit = p2pAuditRequestedRows(d),
        coo = p2pCooFinalRows(d);
    var auditEdited = num(d.audit_team_package_edited) === 1;
    var cooEdited = num(d.coo_management_package_edited) === 1;
    /* Legacy-safe fallback: if a snapshot differs but the old edited flag was not saved, still show the changed version. */
    if (audit.length && !auditEdited && p2pPackageRowsKey(audit) !== p2pPackageRowsKey(branch)) auditEdited = true;
    var cooBase = audit.length ? audit : branch;
    if (coo.length && !cooEdited && p2pPackageRowsKey(coo) !== p2pPackageRowsKey(cooBase)) cooEdited = true;
