var LIFE_PRINT_PRIVACY_ACTIVE = false;
var LIFE_PRINT_PREV_OUTPUT_PRIVACY = false;

function prepareReportPrintPrivacy() {
    if (LIFE_PRINT_PRIVACY_ACTIVE) return;
    LIFE_PRINT_PRIVACY_ACTIVE = true;
    LIFE_PRINT_PREV_OUTPUT_PRIVACY = OUTPUT_PRIVACY_MODE;
    OUTPUT_PRIVACY_MODE = true;
    render();
}

function restoreReportPrintPrivacy() {
    if (!LIFE_PRINT_PRIVACY_ACTIVE) return;
    OUTPUT_PRIVACY_MODE = LIFE_PRINT_PREV_OUTPUT_PRIVACY;
    LIFE_PRINT_PRIVACY_ACTIVE = false;
    render();
    updateMobileMaskAccess();
}

function printReport() {
    prepareReportPrintPrivacy();

    // afterprint covers normal browser behavior; the finally fallback protects
    // browsers where afterprint is delayed or not fired reliably.
    var restored = false;

    function restoreOnce() {
        if (restored) return;
        restored = true;
        restoreReportPrintPrivacy();
    }

    window.addEventListener('afterprint', restoreOnce, {
        once: true
    });

    setTimeout(function() {
        try {
            window.print();
        } finally {
            setTimeout(restoreOnce, 0);
        }
    }, 50);
}

