/* Backwards-compatible alias — nothing else in the file should call the old name. */
var lifeAllFinalCOOBhuvan = lifeAllFinalStage;

/* ---------------------------------------------------------------
   Detect: is this request currently pending at the FINAL
   approval stage for its own category?

   - P2P  → Level 3 (COO / Management)
   - C2C  → Level 3 (COO / Management)
   - B2B  → Level 3 (COO / Management)

   Only the stage matters. No approver-name check is applied.
   --------------------------------------------------------------- */
function lifeIsFinalStage(r){
  if(!r) return false;
  if(r.status !== 'Pending') return false;
  if(['P2P','C2C','B2B'].indexOf(r.type) < 0) return false;

  /* Level 3 = COO / Management in all three chains */
  var s3 = apprAt(r, 3);
  if(!s3 || s3.status !== 'Pending') return false;

  return true;
}

/* Whether EVERY row in the selection qualifies for one-shot bulk approve */
function lifeAllFinalStage(list){
  if(!list || !list.length) return false;
  return list.every(lifeIsFinalStage);
}

/* =====================================================================
   PURCHASE INVOICE — BULK APPROVAL ELIGIBILITY
   Workflow (Purchase Invoice Approval Process):
     Draft
       → [Send for Approval]  → Pending Ops Approval   (Sales Manager)
       → [Approve]            → Pending from CEO        (System Manager)
       → [Approve]            → Approved
       → [Reject]             → Rejected / Draft

   Bulk-approvable states:  Pending Ops Approval, Pending from CEO
   Bulk action:             always "Approve"
   ===================================================================== */

var LIFE_PI_BULK_STATES = ['Pending Ops Approval', 'Pending from CEO'];

/* Only System Manager / Stock Manager can even see PI records (existing rule),
   and only a purchase approver may act. Reuse existing isPurchaseApprover(). */
function lifeIsPurchaseInvoice(r) {
    return !!r && r.type === 'STK' && r.stockSource === 'Purchase Invoice';
}

/* Which PI state is this record in? Returns '' when not bulk-eligible. */
function lifePiBulkState(r) {
    if (!lifeIsPurchaseInvoice(r)) return '';
    if (r.status !== 'Pending') return '';

    var raw = r.raw || {};
    var wf = text(raw.workflow_state || r.workflowState);

    /* Never trust the mapped status alone — the workflow_state field is authoritative. */
    if (LIFE_PI_BULK_STATES.indexOf(wf) < 0) return '';

    return wf;
}

/* Is this specific PI bulk-approvable for the current login? */
function lifeIsPiBulkEligible(r) {
    if (!lifePiBulkState(r)) return false;
    if (!isPurchaseApprover()) return false;
    return true;
}

/* Every selected PI must be in a bulk state. */
function lifeAllPiBulkEligible(list) {
    if (!list || !list.length) return false;
    return list.every(lifeIsPiBulkEligible);
}

/* =====================================================================
   PURCHASE ORDER — BULK APPROVAL ELIGIBILITY
   Workflow (Purchase Order Approval Process):
     Draft
       → [Send for Approval]  → Pending Ops Approval   (Stock Manager)
       → [Approve]            → Approved                (Sales Manager)
       → [Reject]             → Rejected
       → [Edit and Re-submit] → Draft                   (Stock Manager)

   Bulk-approvable state:   Pending Ops Approval
   Bulk action:             always "Approve"
   ===================================================================== */

var LIFE_PO_BULK_STATES = ['Pending Ops Approval'];

function lifeIsPurchaseOrder(r) {
    return !!r && r.type === 'STK' && r.stockSource === 'Purchase Order';
}

/* Which PO state is this record in? Returns '' when not bulk-eligible. */
function lifePoBulkState(r) {
    if (!lifeIsPurchaseOrder(r)) return '';
    if (r.status !== 'Pending') return '';

    var raw = r.raw || {};
    var wf = text(raw.workflow_state || r.workflowState);

    /* workflow_state is authoritative — never trust the mapped status alone. */
    if (LIFE_PO_BULK_STATES.indexOf(wf) < 0) return '';

    return wf;
}

function lifeIsPoBulkEligible(r) {
    if (!lifePoBulkState(r)) return false;
    if (!isPurchaseApprover()) return false;
    return true;
}

function lifeAllPoBulkEligible(list) {
    if (!list || !list.length) return false;
