lifeReviewSelected = async function(){
  var selected = rows().filter(function(r){ return LIFE_SELECTED[r.no]; });
  if(!selected.length) return;

  if(selected.some(function(r){ return lifeUIStatus(r)!=='Pending'; })){
    toast('Select pending requests only','err'); return;
  }
  if(new Set(selected.map(reportTypeKey)).size!==1){
    toast('Select requests from one category only','err'); return;
  }

  /* Hydrate + load server context for each, then show the compact panel */
  showLoad(true,'Checking selected requests…','Validating stage and approver');
  try{
    for(var i=0;i<selected.length;i++){
      var r=selected[i];
      await hydrateRecord(r);
      await loadRecordApprovalActions(r);
    }
    LIFE_BULK_ROWS = selected.map(function(r){ return {r:r}; });
    lifeBulkPanel(selected, selected);
  }catch(e){
    toast('Selection check failed: '+errText(e),'err');
  }finally{
    showLoad(false);
  }
};

lifeBulkApproveAll = async function() {
    if (LIFE_BULK_BUSY) return;
    var list = (LIFE_BULK_ROWS || []).map(function(x) { return x.r; });
    if (!list.length) return;

        var category = reportTypeKey(list[0]);

    /* ---------- PURCHASE INVOICE ---------- */
    if (category === 'PI') {
        return lifeBulkApproveAllPI(list);
    }

    /* ---------- PURCHASE ORDER ---------- */
    if (category === 'PO') {
        return lifeBulkApproveAllPO(list);
    }

    /* ---------- Existing conversion flow (P2P / C2C / B2B) ---------- */
    if (!lifeAllFinalStage(list)) {
        toast('One-shot approval requires the final COO stage for all selected requests', 'err');
        return;
    }

    var remarks  = text((byId('life-bulk-remarks') || {}).value);
    var isB2B    = (category === 'B2B');

    if (isB2B) {
        if (!remarks) {
            toast('Approval remarks are required for B2B COO approval', 'err');
            return;
        }
        if (!LIFE_BULK_SIGNATURE_DATA) {
            toast('Signature is required for B2B COO approval', 'err');
            return;
        }
    }

    if (!confirm('Approve all ' + list.length + ' selected ' + category + ' requests at the COO stage?')) { toast('Approval canceled. No requests were changed.'); return; }

    LIFE_BULK_BUSY = true;
    var results = [];
    try {
        for (var i = 0; i < list.length; i++) {
            var r = list[i];
            showLoad(true, 'Approving ' + (i + 1) + ' / ' + list.length, r.reqId);

            var fresh = await getDoc(r.sourceDoctype, r.sourceName);
            if (fresh.modified !== (r.raw || {}).modified) {
                throw new Error(r.reqId + ' changed on the server. Re-open and retry.');
            }
            r.raw = fresh;
            await loadRecordApprovalActions(r);

            if (!lifeIsFinalStage(r)) {
                throw new Error(r.reqId + ' is no longer pending at the COO / Management stage.');
            }

            var res = await api('life_approval_report_conversion_action', {
                operation: 'action',
                doctype: r.sourceDoctype,
                docname: r.sourceName,
                action: 'Approve',
                remarks: remarks,
                approver_employee: '',
                signature: isB2B ? LIFE_BULK_SIGNATURE_DATA : '',
                table_rows_json: '',
                table_edit_reason: ''
            }) || {};

            results.push(r.reqId + ' — approved');

            if (res.run_p2p_final_automation) {
                var auto = await api('p2p_run_final_automation', { request_name: r.sourceName });
                if (auto && auto.ok === false) {
                    throw new Error(r.reqId + ': approval saved; final automation failed. ' + text(auto.message));
                }
            }
        }
    } catch (e) {
        results.push('Stopped: ' + errText(e) + ' — verify the affected request before retrying.');
    } finally {
        LIFE_BULK_BUSY = false;
        showLoad(false);
        LIFE_DASH_ROWS = null;
        LIFE_MY_ROWS   = null;
        LIFE_SELECTED  = {};
        LIFE_BULK_SIGNATURE_DATA = '';
        await refreshReport();
        lifePanel('Bulk approval results',
            lifeBulkResultsHTML(results)
        );
    }
};

/* =====================================================================
   BULK APPROVE — PURCHASE INVOICE WORKER
   Uses frappe.model.workflow.apply_workflow with action="Approve"
   for each PI. Reloads the doc fresh so the workflow engine sees the
   current workflow_state, then validates the state before applying.
   ===================================================================== */
async function lifeBulkApproveAllPI(list) {
    if (!isPurchaseApprover()) {
        toast('Purchase approval is restricted to KP / Administrator / Bhuvan', 'err');
