  if(/chief operating officer|\bcoo\b/.test(s))return 'coo';
  if(/chief executive officer|\bceo\b/.test(s))return 'ceo';
  if(/managing director|\bmd\b/.test(s))return 'md';
  if(/audit/.test(s))return 'audit';
  if(/purchase manager/.test(s))return 'purchase';
  if(/stock manager/.test(s))return 'stock';
  if(/accounts manager/.test(s))return 'accounts';
  if(/centre manager|center manager|branch manager|\bcm\b|\bacm\b/.test(s))return 'manager';
  return '';
 }
 var assigned=level(title);if(assigned)return assigned;
 /* Bhuvan's configured conversion authority and requested business level is COO. */
 if(normUser(CURRENT_USER)==='bhuvan@lifescc.com')return 'coo';
 var levels=SESSION_ROLES.map(function(r){return level(String(r).toLowerCase());}).filter(Boolean);
 levels=Array.from(new Set(levels));return levels.length===1?levels[0]:'';
}
function lifePersonalPurchaseMatches(r){
 var mine=lifePersonalPurchaseLevel(),stage=lifePiCooLabel(lifeWorkflowStateOf(r),r.stockSource).toLowerCase();
 if(!mine)return false;
 var patterns={coo:/\bcoo\b|chief operating officer/,ceo:/\bceo\b|chief executive officer/,md:/\bmd\b|managing director/,audit:/audit/,purchase:/purchase manager/,stock:/stock manager/,accounts:/accounts manager/,manager:/centre manager|center manager|branch manager|\bcm\b/};
 return !!(patterns[mine]&&patterns[mine].test(stage));
}

async function lifeResolveMine() {
    if (LIFE_MY_ROWS) return LIFE_MY_ROWS;
    var all = await lifeDashboardData(),
        pending = all.filter(function(r) {
            return lifeUIStatus(r) === 'Pending'
        }),
        mine = [],
        cursor = 0,
        done = 0;
    async function worker() {
        while (cursor < pending.length) {
            var r = pending[cursor++],
                ok = false;
            try {
                if (r.type === 'DISC') {
                    ok = discountActionInfo(r).canAct
                } else if (['P2P', 'C2C', 'B2B'].indexOf(r.type) > -1) {
                    await loadRecordApprovalActions(r);
                    ok = Number(lifeConvContext(r).my_queue_can_act) === 1
                } else if (r.type === 'STK' && r.stockSource !== 'Material Request' && isPurchaseApprover() && lifePersonalPurchaseMatches(r)) {
                    await hydrateRecord(r);
                    await loadRecordApprovalActions(r);
                    ok = (r._workflowActions || []).some(function(a) {
                        return /^approve/i.test(String(a))
