/* Toggle a row's checkbox when its select cell is clicked anywhere.
   - respects the existing "disabled" state (non-pending or ineligible rows)
   - never fires when the click came from the checkbox itself (that path
     still calls lifeSelect directly via onchange, so we must not double-toggle)
   - always routes through lifeSelect so all eligibility checks stay intact */
function lifeToggleSelect(cell, no) {
    var cb = cell && cell.querySelector('input[type="checkbox"]');
    if (!cb) return;
    if (cb.disabled) return;              // row is not selectable for any reason
    cb.checked = !cb.checked;
    lifeSelect(no, cb.checked);
}

