        existing = rows().find(function(r) { return LIFE_SELECTED[r.no]; }),
        key = existing ? reportTypeKey(existing) : TYPE;

    if (key === 'ALL' && new Set(pending.map(reportTypeKey)).size > 1) {
        toast('Open one category before selecting all pending requests', 'err');
        return;
    }
    if (key === 'ALL' && pending.length) key = reportTypeKey(pending[0]);

    var pool = pending.filter(function(r) { return reportTypeKey(r) === key; });

        /* For Purchase Invoices / Purchase Orders, only select the ones in a
       bulk-approvable state. */
