lifeBulkReason = function(r) {
    if (lifeUIStatus(r) !== 'Pending') return 'Only pending requests can be approved.';

    var key = reportTypeKey(r);

    /* ---------- Purchase Invoice (new bulk path) ---------- */
    if (key === 'PI') {
        if (!isPurchaseApprover()) return 'Purchase approval is restricted to KP / Administrator / Bhuvan.';
        var piState = lifePiBulkState(r);
        if (!piState) {
            return 'PI must be in "Pending Ops Approval" or "Pending from CEO" to be bulk approved. Current: ' +
                   text((r.raw || {}).workflow_state || r.workflowState, '—');
        }
        return '';   // eligible
    }

        /* ---------- Purchase Order ---------- */
    if (key === 'PO') {
        if (!isPurchaseApprover()) {
            return 'PO bulk approval is restricted to authorised purchase approvers.';
        }
        var poState = lifePoBulkState(r);
        if (!poState) {
            return 'PO must be in "Pending Ops Approval" to be bulk approved. Current: ' +
                   text((r.raw || {}).workflow_state || r.workflowState, '—');
        }
        return '';   // eligible
    }

    /* ---------- Conversion requests (unchanged) ---------- */
    if (['P2P', 'C2C', 'B2B'].indexOf(r.type) < 0) {
        return 'This category requires its existing individual approval process.';
    }

    var c = lifeConvContext(r);
    if (!c.can_act) return c.reason || 'Your login cannot approve this stage.';

    if (r.type === 'B2B') {
        return 'B2B COO approval requires an individual signature. Open each request.';
    }

    if (lifeIsFinalStage(r)) return '';

    if (c.require_signature) return 'Individual signature required.';
    if ((c.centre_managers || []).length) return 'Individual manager selection required.';
    if (c.allow_table_edit) return 'Individual package-table review required.';
    if (c.remarks_required_for_approve) return 'Individual remark required.';
    return '';
};

