 async function json(url){var r=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json'}});
  if(!r.ok){var e=new Error(r.status===401||r.status===403?'Access denied. Sign in again if your session expired, or ask IT to check your approval read access.':'Unable to load the report ('+r.status+'). Please retry.');e.status=r.status;throw e;}return r.json();}
 async function getScope(){var body=await json('/api/method/life_approval_report_user_context'),c=body.message||{},user=c.user;
