  var elevated=c.is_elevated===true||c.is_elevated===1||user==='Administrator'||(c.roles||[]).indexOf('System Manager')>=0;
  var br=(c.branch_permissions||[]).map(function(x){return typeof x==='string'?x:x.for_value;}).filter(Boolean);
  if(!br.length&&c.employee&&c.employee.branch)br=[c.employee.branch];br=Array.from(new Set(br));
  if(!elevated&&!br.length)throw Error('Your login has no assigned branch. Ask IT to set your Branch User Permission or Employee branch.');
  return {elevated:elevated,branches:br,user:user,name:(c.employee&&c.employee.employee_name)||(c.user_info&&c.user_info.full_name)||user};}
 async function loadCat(key){if(key==='disc'||key==='stock')return loadExtra(key);var cfg=CAT[key],all=[],seen={},off=0;
  while(true){var f=S.scope.elevated?[]:[[cfg.branch,'in',S.scope.branches]];
   var url='/api/resource/'+encodeURIComponent(cfg.doctype)+'?fields='+encodeURIComponent(JSON.stringify(COMMON.concat(cfg.fields)))+'&filters='+encodeURIComponent(JSON.stringify(f))+'&order_by='+encodeURIComponent('creation asc, name asc')+'&limit_page_length=500&limit_start='+off;
   var body=await json(url);if(!Array.isArray(body.data))throw Error('Unexpected response for '+cfg.label+'.');var added=0;
   body.data.forEach(function(r){if(!seen[r.name]){seen[r.name]=1;added++;all.push(norm(key,r));}});
