 async function loadExtra(key){
  var discount=key==='disc',cfg=discount?SOURCE_CFG.DISC:STOCK_SOURCE_CFG.MR,all=[],seen=new Set(),off=0;
  while(true){
   var url='/api/resource/'+encodeURIComponent(cfg.doctype)+'?fields='+encodeURIComponent(JSON.stringify(cfg.fields))+'&order_by='+encodeURIComponent('creation asc, name asc')+'&limit_page_length=250&limit_start='+off;
   var body=await json(url);if(!Array.isArray(body.data))throw Error('Unexpected response for '+CAT[key].label+'.');
   var raw=body.data.filter(function(r){if(seen.has(r.name))return false;seen.add(r.name);return true;});
   if(body.data.length&&!raw.length)throw Error('Could not finish loading '+CAT[key].label+'.');
   var normalized=discount?await normalizeRaw('DISC',raw):await normalizeStockSource('MR',raw);
   normalized.forEach(function(r){
    var branch=canonicalBranch(r.branch||'');
    if(!S.scope.elevated&&!S.scope.branches.some(function(b){return canonicalBranch(b)===branch;}))return;
    var d=r.raw||{},status=r.status==='Process Completed'?'Approved':r.status==='Rejected'?'Rejected':'Pending';
    var pending=(r.stages||[]).find(function(s){return s.status==='Pending';});
    var reason=discount?(d.reason||''):(r.stockPurpose||'');
    var remark=discount?(d.rejection_reason||d.approver_note||reason):[r.stockPurpose,r.sourceStatus].filter(Boolean).join(' · ');
    all.push({key:key,id:d.name||r.reqId,client:discount?((r.client||{}).name||'—'):(r.stockPurpose||'Material Request'),branch:branch,to:discount?(r.invoice||'—'):(r.toWarehouse||'—'),date:String(d.creation||r.reqDT||'').slice(0,10),status:status,stage:status==='Pending'?(pending&&pending.role|| (discount?d.approval_level:'Purchase / HO Stock')||'Not recorded'):'',decision:discount&&d.approved_at?String(d.approved_at).slice(0,10):'',amount:discount?r.net:(r.lines&&r.lines.length?r.value:null),remarks:remark,reason:reason,rejection:status==='Rejected'?remark:''});
   });
   S.progress[key]=all.length;renderProgress();off+=body.data.length;
   if(body.data.length<250)break;
  }
  S.progress[key]='done:'+all.length;renderProgress();return all;
 }
 function norm(key,r){var state=P.status(key,r),rank=P.rank(key,r),draft=P.draft(key,r);
  var status=state==='approved'?'Approved':state==='rejected'?'Rejected':state==='review'?'Needs review':draft?'Draft':'Pending';
  var fin=key==='p2p'?r.coo_management_date:key==='c2c'?(r.custom_coo_management_action_datetime||r.operations_coo__management_date):r.final_approval_date;
  var rej=status==='Rejected'?(r.rejection_remarks||r.final_approval_remarks||r.coo_management_remarks||r.operations_final_remarks||r.audit_team_remarks||r.audit_remarks||r.centre_manager_remarks):'';
  var reason=r.reason__remarks_of_conversion||r.reason__remarks_of__conversion||r.reason_for_transfer||'';
  return {key:key,id:r.name,client:r.name1||r.client_full_name||r.client||r.name,branch:r[CAT[key].branch]||'',
   to:key==='c2c'?((r.client_name||'—')+(r.receiving_branch?' · '+r.receiving_branch:'')):key==='b2b'?(r.transfer_to_branch||'—'):'Same client',
   date:String(r.creation||'').slice(0,10),status:status,stage:status==='Pending'?({1:'Centre Manager',2:'Audit Team',3:'COO'}[rank]||'Not recorded'):status==='Draft'?'Not submitted':'',
   decision:fin?String(fin).slice(0,10):'',amount:key==='p2p'?r.new_package_total_price_rs:key==='c2c'?r.total_paid_amount:r.total_received_rs,
   remarks:rej||reason,reason:reason,rejection:rej};}

