 function val(id){return q('#lcr2-'+id).value;}
 function filtered(){var cat=val('cat'),stt=val('status'),br=val('branch'),fr=val('from'),to=val('to'),s=val('search').trim().toLowerCase();
  if(fr&&to&&fr>to)return [];
  var list=S.rows.filter(function(r){return (!cat||r.key===cat)&&(!stt||r.status===stt)&&(!br||r.branch===br)&&(!fr||r.date>=fr)&&(!to||r.date<=to)&&(!s||[r.id,r.client,r.branch,r.to].join(' ').toLowerCase().indexOf(s)>=0);});
  var k=S.sort.k,d=S.sort.d;
  list.sort(function(a,b){var x=a[k],y=b[k];if(k==='amount'){x=Number(x)||0;y=Number(y)||0;return (x-y)*d;}x=String(x||'');y=String(y||'');return x.localeCompare(y)*d||b.date.localeCompare(a.date);});
  return list;}
 function count(list,s){return list.filter(function(r){return r.status===s;}).length;}

